CREATE DATABASE IF NOT EXISTS foodfusion CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE foodfusion;
SET FOREIGN_KEY_CHECKS=0;
DROP TABLE IF EXISTS user_activity,recipe_comments,recipe_ratings,favourites,contact_messages,resources,events,news,recipes,users;
SET FOREIGN_KEY_CHECKS=1;
CREATE TABLE users(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,first_name VARCHAR(80) NOT NULL,last_name VARCHAR(80) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,profile_image VARCHAR(255),role ENUM('user','admin') DEFAULT 'user',failed_login_attempts TINYINT UNSIGNED DEFAULT 0,locked_until DATETIME,last_login DATETIME,last_failed_login DATETIME,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE recipes(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(180) NOT NULL,description TEXT NOT NULL,image VARCHAR(500),cuisine VARCHAR(80),dietary_preference VARCHAR(80) DEFAULT 'General',difficulty ENUM('Easy','Medium','Hard') DEFAULT 'Easy',prep_time SMALLINT UNSIGNED DEFAULT 0,cook_time SMALLINT UNSIGNED DEFAULT 0,servings SMALLINT UNSIGNED DEFAULT 1,ingredients TEXT NOT NULL,instructions TEXT NOT NULL,cooking_tips TEXT,video_url VARCHAR(500),author_id INT UNSIGNED,status ENUM('pending','approved','rejected') DEFAULT 'approved',featured TINYINT(1) DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(author_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE recipe_ratings(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,recipe_id INT UNSIGNED NOT NULL,user_id INT UNSIGNED NOT NULL,rating TINYINT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(recipe_id,user_id),FOREIGN KEY(recipe_id) REFERENCES recipes(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE recipe_comments(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,recipe_id INT UNSIGNED NOT NULL,user_id INT UNSIGNED NOT NULL,comment TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(recipe_id) REFERENCES recipes(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE favourites(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NOT NULL,recipe_id INT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(user_id,recipe_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(recipe_id) REFERENCES recipes(id) ON DELETE CASCADE);
CREATE TABLE events(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(180),description TEXT,image VARCHAR(500),event_date DATE,event_time TIME,location VARCHAR(180),registration_url VARCHAR(255),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE news(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(180),content TEXT,category VARCHAR(80),published TINYINT(1) DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE resources(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(180),description TEXT,category ENUM('Culinary','Education'),type VARCHAR(50),file_path VARCHAR(255),thumbnail VARCHAR(500),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE contact_messages(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,first_name VARCHAR(80),last_name VARCHAR(80),email VARCHAR(190),subject VARCHAR(180),enquiry_type VARCHAR(80),message TEXT,status ENUM('new','read','resolved') DEFAULT 'new',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE user_activity(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED,activity_type VARCHAR(60),description VARCHAR(255),ip_address VARCHAR(45),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL);

