INSERT INTO recipes(title,description,image,cuisine,dietary_preference,difficulty,prep_time,cook_time,servings,ingredients,instructions,cooking_tips,video_url,status,featured) VALUES
('Anzac biscuits','step 1 Heat oven to 180C/fan 160C/gas 4.','https://www.themealdb.com/images/media/meals/q47rkb1762324620.jpg','Australian','General','Medium',30,30,8,'85g Porridge oats\n85g Desiccated Coconut\n100g Plain Flour\n100g Caster Sugar\n100g Butter\n1 tblsp Golden Syrup\n1 teaspoon Bicarbonate Of Soda','step 1\nHeat oven to 180C/fan 160C/gas 4. Put the oats, coconut, flour and sugar in a bowl. Melt the butter in a small pan and stir in the golden syrup. Add the bicarbonate of soda to 2 tbsp boiling water, then stir into the golden syrup and butter mixture.\n\nstep 2\nMake a well in the middle of the dry ingredients and pour in the butter and golden syrup mixture. Stir gently to incorporate the dry ingredients.\n\nstep 3\nPut dessertspoonfuls of the mixture on to buttered baking sheets, about 2.5cm/1in apart to allow room for spreading. Bake in batches for 8-10 mins until golden. Transfer to a wire rack to cool.',NULL,'https://www.youtube.com/watch?v=1nAVbfQVWRQ','approved',1),
('Bubble & Squeak','Melt the fat in a non-stick pan, allow it to get nice and hot, then add the bacon.','https://www.themealdb.com/images/media/meals/xusqvw1511638311.jpg','British','General','Easy',10,10,4,'1 tbs Butter\n4 Bacon\n1 finely sliced Onion\n1 chopped Garlic Clove\n20 Brussels Sprouts\n400g Potatoes','Melt the fat in a non-stick pan, allow it to get nice and hot, then add the bacon. As it begins to brown, add the onion and garlic. Next, add the sliced sprouts or cabbage and let it colour slightly. All this will take 5-6 mins.\nNext, add the potato. Work everything together in the pan and push it down so that the mixture covers the base of the pan – allow the mixture to catch slightly on the base of the pan before turning it over and doing the same again. It’s the bits of potato that catch in the pan that define the term ‘bubble and squeak’, so be brave and let the mixture colour. Cut into wedges and serve.',NULL,'https://www.youtube.com/watch?v=etbJ9ssgsWY','approved',1),
('BeaverTails','In the bowl of a stand mixer, add warm water, a big pinch of sugar and yeast.','https://www.themealdb.com/images/media/meals/ryppsv1511815505.jpg','Canadian','General','Hard',15,20,8,'1/2 cup Water\n2 parts Yeast\n1/2 cup Sugar\n1/2 cup Milk\n6 tblsp Butter\n2 Eggs\n1 ½ tsp Salt\n2-1/2 cups Flour\nfor frying Oil\ngarnish Lemon\ngarnish Sugar\ngarnish Cinnamon','In the bowl of a stand mixer, add warm water, a big pinch of sugar and yeast. Allow to sit until frothy.\nInto the same bowl, add 1/2 cup sugar, warm milk, melted butter, eggs and salt, and whisk until combined.\nPlace a dough hook on the mixer, add the flour with the machine on, until a smooth but slightly sticky dough forms.\nPlace dough in a bowl, cover with plastic wrap, and allow to proof for 1 1/2 hours.\nCut dough into 12 pieces, and roll out into long oval-like shapes about 1/4 inch thick that resemble a beaver’s tail.\nIn a large, deep pot, heat oil to 350 degrees. Gently place beavertail dough into hot oil and cook for 30 to 45 seconds on each side until golden brown.\nDrain on paper towels, and garnish as desired. Toss in cinnamon sugar, in white sugar with a squeeze of lemon, or with a generous slathering of Nutella and a handful of toasted almonds. Enjoy!',NULL,'https://www.youtube.com/watch?v=2G07UOqU2e8','approved',1),
('Air Fryer Egg Rolls','Alternative Pan Fry Method: If you don’t have access to an air fryer, you can make these egg rolls using a traditional pan fry method.','https://www.themealdb.com/images/media/meals/grhn401765687086.jpg','Chinese','General','Hard',20,60,6,'1 tablespoon Olive Oil\n1 lb Ground Pork\n1 clove peeled crushed Garlic\n1 tablespoon Ginger\n1 medium Carrots\n3 chopped Scallions\n3 Cups Cabbage\n1 tablespoon Soy Sauce\n1 tablespoon Rice Vinegar\n12 Egg Roll Wrappers\nFor brushing Oil\nTo serve Duck Sauce\nTo serve Plum Sauce\nTo serve Soy Sauce','Alternative Pan Fry Method: If you don’t have access to an air fryer, you can make these egg rolls using a traditional pan fry method. Add enough oil to a medium skillet with high walls so the oil is about 1/2 inch up the side of the skillet. Heat oil on medium high heat until it reaches 350°F. Add egg rolls and fry for 3 to 4 minutes, flip, and fry for another 3 to 4 minutes until golden brown. Remove and let them drain and cool on a few paper towels.\n\nCook the filling:\nIn a large skillet over medium heat, add the olive oil along with the ground pork or chicken. Break apart the meat with a spatula or wooden spoon as it cooks. Cook until the meat is cooked through, 6 to 8 minutes.\n\nAdd garlic, ginger, carrot, scallions, and cabbage. Continue to cook until cabbage wilts down and is soft, another 3 to 4 minutes, stirring regularly. Season the filling with soy sauce and rice wine vinegar, and take off the heat to cool. (This filling can be made in advance.)\n\nAssemble the egg rolls:\nPlace a single egg roll wrapper on a dry surface with one point of the square facing you (like a diamond). Place about 1/4 cup of the egg roll filling mixture in the middle of the wrapper.\n\nDip your fingers in water and run around the edges of the wrapper. Then fold the edges of the wrapper over the center and start rolling the egg roll away from you to form a tight cylinder. Place on a plate and repeat until you are out of filling. You should get at least a dozen egg rolls.\n\nAir fry the egg rolls:\nPlace the egg rolls in the basket of your air fryer. Spray or brush them lightly with oil. Add as many as you can without stacking the egg rolls, making sure they don’t touch. Air needs to circulate around them. Brush the egg rolls lightly with oil.\n\nPlace the basket in the air fryer and turn the air fryer to 350°F. Cook for 6 to 7 minutes, then flip the egg rolls, spray or brush with oil a second time on the bottom side, and cook for another 4 to 5 minutes.\n\nFinished egg rolls should be golden brown and crispy! Serve immediately.',NULL,'https://www.youtube.com/watch?v=XnA-wcVb4l0','approved',1),
('Burek','Fry the finely chopped onions and minced meat in oil.','https://www.themealdb.com/images/media/meals/tkxquw1628771028.jpg','Croatian','General','Easy',15,10,6,'1 Packet Filo Pastry\n150g Minced Beef\n150g Onion\n40g Oil\nDash Salt\nDash Pepper','Fry the finely chopped onions and minced meat in oil. Add the salt and pepper. Grease a round baking tray and put a layer of pastry in it. Cover with a thin layer of filling and cover this with another layer of filo pastry which must be well coated in oil. Put another layer of filling and cover with pastry. When you have five or six layers, cover with filo pastry, bake at 200ºC/392ºF for half an hour and cut in quarters and serve.',NULL,'https://www.youtube.com/watch?v=YsJXZwE5pdY','approved',1),
('Egyptian Fatteh','To prepare bread for bottom of dish: Take pita bread and rip into bite size pieces.','https://www.themealdb.com/images/media/meals/rlwcc51598734603.jpg','Egyptian','General','Hard',20,70,4,'1lb Beef\n1 Onion\n1 Chicken Stock Cube\n2 Tomatoes\n4 Garlic Clove\n1 tbs Tomato Puree\n2 cups Rice\n1/4 cup Noodles\n1/4 cup Butter\n2 cups Olive Oil\n1 Pita Bread\n1 tbs Cumin\n3 tbs White Wine Vinegar\nTo taste Salt\nTo taste Pepper','To prepare bread for bottom of dish: Take pita bread and rip into bite size pieces. In a frying pan, add about a 1/4 stick of butter, add bread pieces and fry until golden brown and crisp. Put these pieces in a glass baking dish, preferably a square sized dish. Set aside.\nThen add to same pan, a little more butter, salt, approximately 2 cloves of crushed fresh garlic, and a teaspoon or so of cumin stir around a bit until you can smell aroma, then add fried bread pieces to this mixture, stir to coat bread and put back into glass baking dish. Set aside.\nTo prepare meat: put some butter in a pot, stir fry meat until brown, add 1 onion quartered, salt & pepper, 1 cube of chicken bouillon and water to cover meat. Bring to a boil, turn down to simmer, cover and cook until tender, approximately 2 hours. After meat has cooled, take out chunks of meat and put in a bowl, set aside. Reserve soup from the meat separately.\nTo prepare the rice: Put some butter into a pot, add shareya (fideo noodles) like a handful or so, keep stirring until golden brown, not too dark, but very golden. Then add two cups of rice, stir a little bit until some of the rice turns an opaque white. Add 2-1/4 cups of water and salt to taste. Bring to a boil, cover and turn down to simmer, cook until tender. Test the rice tenderness after about 35 minutes.\nNow take some of the soup from meat and add to the top of the bread pieces in baking dish to saturate.Add cooked rice on top of bread pieces. Slowly spoon remainder of soup onto rice, looking at glass dish sides to see level of soup, should reach just to top of rice, don’t worry, this doesn’t have to be exact. Now you’re ready to make the sauce and fry the meat to put on top.\nTo prepare red sauce: In a pan, add a little oil or butter, crushed tomato, a half teaspoon of tomato paste, salt & pepper, 2 cloves of fresh crushed garlic and cumin. Add also approximately 3 tablespoons of vinegar, stir this until you smell aroma and it is a bit smooth. It should be a bit thick, not watery, but if too thick you can add a bit of water. Spread with a wooden spoon atop the rice to cover.\nTo fry meat: In a pan add a bit of butter or oil, the meat, just a touch of tomato paste, about a tablespoon of fresh crushed garlic, salt & pepper, a teaspoon of cumin. Cook until meat is golden fried.\nSpoon this atop the rice and serve. Enjoy!',NULL,'https://www.youtube.com/watch?v=WLuOHkDE4A4','approved',1),
('Beef Asado','0. Combine beef, crushed peppercorn, soy sauce, vinegar, dried bay leaves, lemon, and tomato sauce.','https://www.themealdb.com/images/media/meals/pkopc31683207947.jpg','Filipino','General','Hard',10,50,4,'1.5kg Beef\n1 Beef Stock Concentrate\n8 ounces Tomato Puree\n3 cups Water\n6 tablespoons Soy Sauce\n1 tbs White Wine Vinegar\n2 tbs Pepper\n4 Bay Leaf\n1/2 Lemon\n2 tbs Tomato Sauce\n3 tbs Butter\n1/2 cup Olive Oil\n1 chopped Onion\n4 cloves Garlic','0.\tCombine beef, crushed peppercorn, soy sauce, vinegar, dried bay leaves, lemon, and tomato sauce. Mix well. Marinate beef for at least 30 minutes.\n1.\tPut the marinated beef in a cooking pot along with remaining marinade. Add water. Let boil.\n2.\tAdd Knorr Beef Cube. Stir. Cover the pot and cook for 40 minutes in low heat.\n3.\tTurn the beef over. Add tomato paste. Continue cooking until beef tenderizes. Set aside.\n4.\tHeat oil in a pan. Fry the potato until it browns. Turn over and continue frying the opposite side. Remove from the pan and place on a clean plate. Do the same with the carrots.\n5.\tSave 3 tablespoons of cooking oil from the pan where the potato was fried. Saute onion and garlic until onion softens.\n6.\tPour-in the sauce from the beef stew. Let boil. Add the beef. Cook for 2 minutes.\n7.\tAdd butter and let it melt. Continue cooking until the sauce reduces to half.',NULL,'https://www.youtube.com/watch?v=lNlK8DVhXXA','approved',1),
('Chicken Quinoa Greek Salad','Cook the quinoa following the pack instructions, then rinse in cold water and drain thoroughly.','https://www.themealdb.com/images/media/meals/k29viq1585565980.jpg','Greek','General','Hard',10,10,4,'225g Quinoa\n25g Butter\n1 chopped Red Chilli\n1 clove finely chopped Garlic\n400g Chicken Breast\n2 tbs Olive Oil\nHandful Black Olives\n1 chopped Red Onions\n100g Feta\nChopped Mint\nJuice of 1/2 Lemon','Cook the quinoa following the pack instructions, then rinse in cold water and drain thoroughly.\n\nMeanwhile, mix the butter, chilli and garlic into a paste. Toss the chicken fillets in 2 tsp of the olive oil with some seasoning. Lay in a hot griddle pan and cook for 3-4 mins each side or until cooked through. Transfer to a plate, dot with the spicy butter and set aside to melt.\n\nNext, tip the tomatoes, olives, onion, feta and mint into a bowl. Toss in the cooked quinoa. Stir through the remaining olive oil, lemon juice and zest, and season well. Serve with the chicken fillets on top, drizzled with any buttery chicken juices.',NULL,'https://www.youtube.com/watch?v=akcrkXYr61M','approved',1),
('Boxty Breakfast','STEP 1 Before you start, put your oven on its lowest setting, ready to keep things warm.','https://www.themealdb.com/images/media/meals/naqyel1608588563.jpg','Irish','General','Hard',15,50,4,'4 large Potatoes\n1  bunch Spring Onions\n100g Plain Flour\n1 Egg White\n150ml Milk\n1 tsp Bicarbonate Of Soda\n3 tbs Butter\n2 tbs Vegetable Oil\n6 Cherry Tomatoes\n12 Bacon\n6 Egg','STEP 1\nBefore you start, put your oven on its lowest setting, ready to keep things warm. Peel the potatoes, grate 2 of them, then set aside. Cut the other 2 into large chunks, then boil for 10-15 mins or until tender. Meanwhile, squeeze as much of the liquid from the grated potatoes as you can using a clean tea towel. Mash the boiled potatoes, then mix with the grated potato, spring onions and flour.\n\nSTEP 2\nWhisk the egg white in a large bowl until it holds soft peaks. Fold in the buttermilk, then add the bicarbonate of soda. Fold into the potato mix.\n\nSTEP 3\nHeat a large non-stick frying pan over a medium heat, then add 1 tbsp butter and some of the oil. Drop 3-4 spoonfuls of the potato mixture into the pan, then gently cook for 3-5 mins on each side until golden and crusty. Keep warm on a plate in the oven while you cook the next batch, adding more butter and oil to the pan before you do so. You will get 16 crumpet-size boxty from the mix. Can be made the day ahead, drained on kitchen paper, then reheated in a low oven for 20 mins.\n\nSTEP 4\nHeat the grill to medium and put the tomatoes in a heavy-based pan. Add a good knob of butter and a little oil, then fry for about 5 mins until softened. Grill the bacon, then pile onto a plate and keep warm. Stack up the boxty, bacon and egg, and serve the tomatoes on the side.',NULL,'https://www.youtube.com/watch?v=80W0mCFDIP0','approved',1),
('Budino Di Ricotta','Mash the ricotta and beat well with the egg yolks, stir in the flour, sugar, cinnamon, grated lemon rind and the rum and mix well.','https://www.themealdb.com/images/media/meals/1549542877.jpg','Italian','General','Medium',30,70,8,'500g Ricotta\n4 large Eggs\n3 tbs Flour\n250g Sugar\n1 tsp Cinnamon\nGrated Zest of 2 Lemons\n5 tbs Dark Rum\nsprinking Icing Sugar','Mash the ricotta and beat well with the egg yolks, stir in the flour, sugar, cinnamon, grated lemon rind and the rum and mix well. You can do this in a food processor. Beat the egg whites until stiff, fold in and pour into a buttered and floured 25cm cake tin. Bake in the oven at 180ºC/160ºC fan/gas 4 for about 40 minutes, or until it is firm.\n\nServe hot or cold dusted with icing sugar.',NULL,'https://www.youtube.com/watch?v=6dzd6Ra6sb4','approved',0),
('Brown Stew Chicken','Squeeze lime over chicken and rub well.','https://www.themealdb.com/images/media/meals/sypxpx1515365095.jpg','Jamaican','General','Hard',15,70,4,'1 whole Chicken\n1 chopped Tomato\n2 chopped Onions\n2 chopped Garlic Clove\n1 chopped Red Pepper\n1 chopped Carrots\n1 Lime\n2 tsp Thyme\n1 tsp Allspice\n2 tbs Soy Sauce\n2 tsp Cornstarch\n2 cups Coconut Milk\n1 tbs Vegetable Oil','Squeeze lime over chicken and rub well. Drain off excess lime juice.\nCombine tomato, scallion, onion, garlic, pepper, thyme, pimento and soy sauce in a large bowl with the chicken pieces. Cover and marinate at least one hour.\nHeat oil in a dutch pot or large saucepan. Shake off the seasonings as you remove each piece of chicken from the marinade. Reserve the marinade for sauce.\nLightly brown the chicken a few pieces at a time in very hot oil. Place browned chicken pieces on a plate to rest while you brown the remaining pieces.\nDrain off excess oil and return the chicken to the pan. Pour the marinade over the chicken and add the carrots. Stir and cook over medium heat for 10 minutes.\nMix flour and coconut milk and add to stew, stirring constantly. Turn heat down to minimum and cook another 20 minutes or until tender.',NULL,'https://www.youtube.com/watch?v=_gFB1fkNhXs','approved',0),
('Chicken Karaage','Add the ginger, garlic, soy sauce, sake and sugar to a bowl and whisk to combine.','https://www.themealdb.com/images/media/meals/tyywsw1505930373.jpg','Japanese','General','Medium',10,30,4,'450 grams Boneless skin Chicken\n1 tablespoon Ginger\n1 clove Garlic\n2 tablespoons Soy sauce\n1 tablespoon Sake\n2 teaspoon Granulated sugar\n1/3 cup Potato starch\n1/3 cup Vegetable oil\n1/3 cup Lemon','Add the ginger, garlic, soy sauce, sake and sugar to a bowl and whisk to combine. Add the chicken, then stir to coat evenly. Cover and refrigerate for at least 1 hour.\n\nAdd 1 inch of vegetable oil to a heavy bottomed pot and heat until the oil reaches 360 degrees F. Line a wire rack with 2 sheets of paper towels and get your tongs out. Put the potato starch in a bowl\n\nAdd a handful of chicken to the potato starch and toss to coat each piece evenly.\n\nFry the karaage in batches until the exterior is a medium brown and the chicken is cooked through. Transfer the fried chicken to the paper towel lined rack. If you want the karaage to stay crispy longer, you can fry the chicken a second time, until it\'s a darker color after it\'s cooled off once. Serve with lemon wedges.',NULL,'https://www.youtube.com/watch?v=XivddFddthc','approved',0),
('Apam balik','Mix milk, oil and egg together.','https://www.themealdb.com/images/media/meals/adxcbq1619787919.jpg','Malaysian','General','Medium',20,40,8,'200ml Milk\n60ml Oil\n2 Eggs\n1600g Flour\n3 tsp Baking Powder\n1/2 tsp Salt\n25g Unsalted Butter\n45g Sugar\n3 tbs Peanut Butter','Mix milk, oil and egg together. Sift flour, baking powder and salt into the mixture. Stir well until all ingredients are combined evenly.\n\nSpread some batter onto the pan. Spread a thin layer of batter to the side of the pan. Cover the pan for 30-60 seconds until small air bubbles appear.\n\nAdd butter, cream corn, crushed peanuts and sugar onto the pancake. Fold the pancake into half once the bottom surface is browned.\n\nCut into wedges and best eaten when it is warm.',NULL,'https://www.youtube.com/watch?v=6R8ffRRJcrg','approved',0),
('Braised Beef Chilli','Preheat the oven to 120C/225F/gas mark 1.','https://www.themealdb.com/images/media/meals/uuqvwu1504629254.jpg','Mexican','General','Hard',15,50,4,'1kg Beef\n3 Onions\n4 cloves Garlic\nDash Olive oil\n300g Chorizo\n2 tsp Cumin\n2 tsp Allspice\n1 tsp Cloves\n1 large Cinnamon stick\n3 Bay Leaves\n2 tsp dried Oregano\n2 ancho Ancho Chillies\n3 tbsp Balsamic Vinegar\n2 x 400g Plum Tomatoes\n2 tbsp Tomato Ketchup\n2 tbsp Dark Brown Sugar\n2 x 400g tins Borlotti Beans','Preheat the oven to 120C/225F/gas mark 1.\n\nTake the meat out of the fridge to de-chill. Pulse the onions and garlic in a food processor until finely chopped. Heat 2 tbsp olive oil in a large casserole and sear the meat on all sides until golden.\n\nSet to one side and add another small slug of oil to brown the chorizo. Remove and add the onion and garlic, spices, herbs and chillies then cook until soft in the chorizo oil. Season with salt and pepper and add the vinegar, tomatoes, ketchup and sugar.\n\nPut all the meat back into the pot with 400ml water (or red wine if you prefer), bring up to a simmer and cook, covered, in the low oven.\n\nAfter 2 hours, check the meat and add the beans. Cook for a further hour and just before serving, pull the meat apart with a pair of forks.',NULL,'https://www.youtube.com/watch?v=z4kSoJgsu6Y','approved',0),
('Chicken Couscous','Heat the olive oil in a large frying pan and cook the onion for 1-2 mins just until softened.','https://www.themealdb.com/images/media/meals/qxytrx1511304021.jpg','Moroccan','General','Medium',15,10,4,'1 tbsp Olive Oil\n1 chopped Onion\n200g Chicken Breast\npinch Ginger\n2 tblsp Harissa Spice\n10 Dried Apricots\n220g Chickpeas\n200g Couscous\n200ml Chicken Stock\nHandful Coriander','Heat the olive oil in a large frying pan and cook the onion for 1-2 mins just until softened. Add the chicken and fry for 7-10 mins until cooked through and the onions have turned golden. Grate over the ginger, stir through the harissa to coat everything and cook for 1 min more.\n\nTip in the apricots, chickpeas and couscous, then pour over the stock and stir once. Cover with a lid or tightly cover the pan with foil and leave for about 5 mins until the couscous has soaked up all the stock and is soft. Fluff up the couscous with a fork and scatter over the coriander to serve. Serve with extra harissa, if you like.',NULL,'https://www.youtube.com/watch?v=GZQGy9oscVk','approved',0),
('Beetroot & red cabbage sauerkraut','step 1 Tip all the ingredients into a large bowl, add 1-1½ tsp freshly ground black pepper, then scrunch it all together with your hands for 5 mins.','https://www.themealdb.com/images/media/meals/ra2k8a1764365055.jpg','Polish','Vegetarian','Easy',20,30,4,'320g Beetroot\n450g Red Cabbage\n1 small Onion\n2 tsp Caraway Seed\n1 tsp Sea Salt','step 1\nTip all the ingredients into a large bowl, add 1-1½ tsp freshly ground black pepper, then scrunch it all together with your hands for 5 mins. You might want to wear gloves to avoid staining your skin with the beetroot juices.\n\nstep 2\nPress the veg down in the bowl with your hands, then cover the surface and up the side of the bowl with a large sheet of compostable cling film or something reusable like a beeswax wrap. Now place another similar-sized bowl on top. Press down hard and add anything heavy (packs of rice or cans work well) to weigh it down so the juices rise to cover the surface. Cover again.\n\nstep 3\nLeave to ferment at room temperature for at least five days, but for maximum flavour, leave for one-five weeks (until the bubbling subsides).\n\nstep 4\nCheck the sauerkraut. After a few days, you will see bubbles that have built up as it ferments. Give it a stir, then cover and weigh it down again as before. The cabbage will become increasingly sour the longer it’s fermented, so taste it now and again. When you like the flavour, transfer it to sterilised jars and keep chilled. Will keep chilled for up to six months.',NULL,'https://www.youtube.com/watch?v=ly1UeAjydEg','approved',0),
('Fish fofos','STEP 1 Put the fish into a lidded pan and pour over enough water to cover.','https://www.themealdb.com/images/media/meals/a15wsa1614349126.jpg','Portuguese','General','Hard',20,50,4,'600g Haddock\n300g Potatoes\n1 chopped Green Chilli\n3 tbs Coriander\n1 tsp Cumin Seeds\n1/2 tsp Pepper\n3 cloves Garlic\n2 pieces Ginger\n2 tbs Flour\n3 Eggs\n75g Breadcrumbs\nFor frying Vegetable Oil','STEP 1\n\nPut the fish into a lidded pan and pour over enough water to cover. Bring to a simmer and gently poach for 10 minutes over a low heat with the lid on. Drain and flake the fish.\n\nSTEP 2\n\nPut the fish, potato, green chilli, coriander, cumin, black pepper, garlic and ginger in a large bowl. Season, add the rice flour, mix well and break in 1 egg. Stir the mixture and divide into 15, then form into small logs. Break the remaining eggs into a bowl and whisk lightly. Put the breadcrumbs into another bowl. Dip each fofo in the beaten egg followed by the breadcrumb mixture. Chill for 20 minutes.\n\nSTEP 3\n\nHeat 1cm of oil in a large frying pan over a medium heat. Fry the fofos in batches for 2 minutes on each side, turning gently to get an even golden brown colour all over. Drain on kitchen paper and repeat with the remaining fofos.\n\nSTEP 4\n\nFor the onion salad, mix together the onion, coriander and lemon juice with a pinch of salt. Serve with the fofos and mango chutney.',NULL,'https://www.youtube.com/watch?v=YXUZHK2PrV8','approved',0),
('Beef stroganoff','Heat the olive oil in a non-stick frying pan then add the sliced onion and cook on a medium heat until completely softened, so around 15 mins, adding a little splash of water if they start to stick at all.','https://www.themealdb.com/images/media/meals/svprys1511176755.jpg','Russian','General','Hard',25,60,4,'1 tbls Olive Oil\n1 Onions\n1 clove Garlic\n1 tbsp Butter\n250g Mushrooms\n500g Beef Fillet\n1tbsp Plain Flour\n150g Creme Fraiche\n1 tbsp English Mustard\n100ml Beef Stock\nTopping Parsley','Heat the olive oil in a non-stick frying pan then add the sliced onion and cook on a medium heat until completely softened, so around 15 mins, adding a little splash of water if they start to stick at all. Crush in the garlic and cook for a 2-3 mins further, then add the butter. Once the butter is foaming a little, add the mushrooms and cook for around 5 mins until completely softened. Season everything well, then tip onto a plate.\nTip the flour into a bowl with a big pinch of salt and pepper, then toss the steak in the seasoned flour. Add the steak pieces to the pan, splashing in a little oil if the pan looks particularly dry, and fry for 3-4 mins, until well coloured. Tip the onions and mushrooms back into the pan. Whisk the crème fraîche, mustard and beef stock together, then pour into the pan. Cook over a medium heat for around 5 mins. Scatter with parsley, then serve with pappardelle or rice.',NULL,'https://www.youtube.com/watch?v=PQHgQX1Ss74','approved',0),
('Chicken Shawarma with homemade garlic herb yoghurt sauce','1 Start by cutting your chicken up into reasonably small slices.','https://www.themealdb.com/images/media/meals/hcg6l91763596970.jpg','Saudi Arabian','General','Hard',25,50,4,'1kg Chicken Breast\n2 cloves minced Garlic\n1 tblsp Ground Coriander\n1 tblsp Ground Cumin\n1 tblsp Ground Cardomom\n1 tsp Cayenne Pepper\n2 tsp Smoked Paprika\n2 tsp Salt\n2 tblsp Lemon Juice\n3 tablespoons Olive Oil\n1 cup Greek Yogurt\n1 clove peeled crushed Garlic\n1 tsp Cumin\nSplash Lemon Juice','1\nStart by cutting your chicken up into reasonably small slices. Grab your ziplock bag and dump the freshly sliced chicken inside.\n2\nAdd garlic, coriander, cumin, cardomom, cayenne pepper, paprika, salt, pepper, lemon juice and olive oil to the bag. Close the bag and mix thoroughly. Place in fridge for 10-12 hours (shorter is fine but longer is better).\n3\nOnce ready to cook, heat your fry pan to medium-high and add a tiny bit of olive oil. Fry one side of all of your flatbreads until slightly toasty. Remove from pan, add enough oil to coat the fry pan. Put crumble fries into air fryer on 180 for 15 minutes shaking occasionally.\n4\nThe pan should be pretty hot by now, add the chicken in 2 batches (unless you have a big fry pan) to avoid overcrowding. The chicken should get a nice sear and darker colour which is perfect. Cook for a further 5-8 minutes or until cooked through. Repeat with next chicken batch.\n5\nWhile chicken is cooking, place your Greek yoghurt into a bowl. Combine garlic, finely chopped mint and parsley, squeeze or so of lemon and cumin. Combine and add salt to taste. In a small bowl, combine 1tsp garlic powder, paprika, cumin, onion powder, oregano, dried parsley, cayenne pepper (optional) mix and leave aside for fries.\n6\nSeason fries immediately once cooked and add salt to taste. Once the chicken is complete, serve immediately by laying out your flatbread, spreading the sauce evenly over the bread, add lettuce, onion, tomato, fries, chicken, feta and more sauce on top. Serve immediately.',NULL,'https://www.youtube.com/watch?v=TROZvPHqP1g','approved',0),
('Air fryer patatas bravas','step 1 Soak the potatoes in just-boiled water for 30 mins, then drain and leave to air-dry for 5 mins.','https://www.themealdb.com/images/media/meals/3m8yae1763257951.jpg','Spanish','Vegetarian','Medium',25,10,4,'900g Potatoes\n3  tablespoons Olive Oil\n1 chopped Onion\n1 clove peeled crushed Garlic\n1 tblsp Paprika\n1 tblsp Tomato Puree\n225g Tinned Tomatos\nTo serve Basil Leaves','step 1\nSoak the potatoes in just-boiled water for 30 mins, then drain and leave to air-dry for 5 mins. Heat the air fryer to 200C. Tip the potatoes into a bowl and drizzle over 1 tbsp of the oil and add 1/2 tsp each of salt and freshly ground black pepper. Mix to coat the potatoes all over, then tip into the air fryer basket and cook for 20-30 mins until crisp and golden.\n\nstep 2\nMeanwhile, heat the remaining oil in a small pan over a medium-low heat and fry the onion for 8-10 mins until softened but not golden. Stir in the garlic and cook for a minute before adding the paprika and cooking for 30 seconds more. Stir in the tomato purée, cook for 1 min, then tip in the chopped tomatoes. Cook for 5-10 mins over a medium heat until thickened slightly.\n\nstep 3\nOnce the potatoes are cooked, tip out onto a platter and pour over the tomato sauce. Sprinkle with the basil leaves, then serve.',NULL,'https://www.youtube.com/watch?v=kzLaw6PG2UY','approved',0),
('Baba Ghanoush','Preheat an outdoor grill for medium-high heat and lightly oil the grate.','https://www.themealdb.com/images/media/meals/dlmh401760524897.jpg','Syrian','General','Medium',5,70,6,'4 large Egg Plants\n2 cloves Garlic\n2 teaspoons Kosher Salt\n1 Lemon\n3  tablespoons Tahini\n3  tablespoons Extra Virgin Olive Oil\n2 tablespoons Greek Yogurt\n1 pinch Cayenne Pepper\n1 Leaf Mint\n2 tablespoons Parsley','Preheat an outdoor grill for medium-high heat and lightly oil the grate. Prick the surface of the skin of eggplants several times with the tip of a knife.\n\nPlace eggplants directly on grill. Turn frequently with tongs while skin chars. Cook until eggplants have collapsed and are very soft, 25 to 30 minutes. Transfer to a bowl and cover tightly with aluminum foil and allow to cool, about 15 minutes.\n\nWhen eggplants are cool enough to handle, split them in half and scrape flesh into a colander placed over a bowl. Drain 5 or 10 minutes.\n\nTransfer eggplant to mixing bowl. Add crushed garlic and salt; mash until creamy but with a little texture, about 5 minutes. Whisk in lemon juice, tahini, olive oil, and cayenne pepper. Stir in yogurt.\n\nCover bowl with plastic wrap and refrigerate until completely chilled. Stir in mint and parsley, and taste to adjust seasonings before serving.',NULL,'https://www.youtube.com/watch?v=Mz-ZVfOA_ig','approved',0),
('Drunken noodles (pad kee mao)','step 1 Prepare the noodles following pack instructions, then drain and set aside.','https://www.themealdb.com/images/media/meals/2wx8cm1763373419.jpg','Thai','General','Hard',20,10,4,'200g Flat Rice Noodles\n2 tblsp Vegetable Oil\n3 cloves Chopped Garlic\n3 chopped Birds-eye Chillies\n225g Sirloin steak\n100g Broccoli\nHandful Basil Leaves\n4 tbsp Soy Sauce\n4 tbsp Oyster Sauce\n1 teaspoon Fish Sauce\n1 tblsp Sugar','step 1\nPrepare the noodles following pack instructions, then drain and set aside. Combine all the ingredients for the sauce in a small bowl or jug, and set aside.\n\nstep 2\nHeat the oil in a large wok or frying pan over a high heat and stir-fry the garlic and chilli for 20 seconds until just starting to turn golden. Add the steak and stir-fry for 1 minute until seared and starting to brown. Add the broccoli and stir-fry for another minute, then tip in the noodles and add the sauce. Stir-fry for another 1-2 mins until well combined and piping hot.\n\nstep 3\nStir through the basil and turn off the heat. Serve immediately to avoid overcooking.',NULL,'https://www.youtube.com/watch?v=eJ3w2iJB4x8','approved',0),
('Cashew Ghoriba Biscuits','Preheat the oven at 180 C / Gas 4.','https://www.themealdb.com/images/media/meals/t3r3ka1560461972.jpg','Tunisian','General','Easy',15,10,8,'250g Cashew Nuts\n100g Icing Sugar\n2 Egg Yolks\n2 tbs Orange Blossom Water\nTo Glaze Icing Sugar\n100g Almonds','Preheat the oven at 180 C / Gas 4. Line a baking tray with greaseproof paper.\nIn a bowl, mix the cashews and icing sugar. Add the egg yolks and orange blossom water and mix to a smooth homogeneous paste.\nTake lumps of the cashew paste and shape into small balls. Roll the balls in icing sugar and transfer to the baking tray. Push an almond in the centre of each ghribia.\nBake until the biscuits are lightly golden, about 20 minutes. Keep an eye on them, they burn quickly.',NULL,'https://www.youtube.com/watch?v=IqXEZUk4hWI','approved',0),
('Adana kebab','step 1 Finely chop the peppers in a food processor, then tip them in a sieve and press into the sieve so that the peppers release all of their juices.','https://www.themealdb.com/images/media/meals/04axct1763793018.jpg','Turkish','General','Easy',5,70,4,'2 large Romano Pepper\n800g Lamb Mince\n3  tablespoons Red Pepper Paste\n1 tablespoon Pul Biber\n3  tablespoons Sunflower Oil','step 1\nFinely chop the peppers in a food processor, then tip them in a sieve and press into the sieve so that the peppers release all of their juices. Tip into a bowl along with the mince, red pepper paste, pul biber, 1½ tsp flaky sea salt, and 2 tbsp of the oil. Mix together, kneading well for at least 2-3 mins. If you need to, wet your hands with cold water to prevent the mixture from sticking. The mixture should be sticky when ready. Cover and chill for at least 2 hrs, or up to 12 hrs.\n\nstep 2\nWhen ready to cook, heat the grill to high or an oven to 220C/200C fan/gas 6. Divide the mixture into 12 equal portions, around 85g each. If you’d like to skewer them, divide into 8 equal portions and roll into balls. Using wet hands, thread the balls onto the end of the skewers, massaging the mixture down the skewers in between the palms of your hands, until evenly distributed. Ensure that the mixture is fully wrapped tightly around the skewers without any exposed metal. Alternatively, lay them on a large baking tray lined with parchment paper if cooking in the oven, or foil if cooking under the grill. Shape into 20cm-long köfte. Wet your fingers with a little cold water and make indents all along the köfte for the traditional shape.\n\nstep 3\nGently brush each köfte with the remaining 1 tbsp oil and cook under the grill, on the top shelf for 10-12 mins, turning regularly, or cook in the oven for 16-18 mins, until crispy on the outside and juicy in the middle',NULL,'https://www.youtube.com/watch?v=Wj7sXu9B_ME','approved',0),
('Beetroot latkes','step 1 Heat the oven to 180C/160C fan/gas 4.','https://www.themealdb.com/images/media/meals/qwicc91764368097.jpg','Ukrainian','Vegetarian','Hard',20,20,4,'1 tablespoon Rapeseed Oil\n4 tablespoons Greek Yogurt\n1/2 bag Mint\n150g Rocket\n130g Cherry Tomatoes\n400g Beetroot\n1 beaten Egg\n1 tablespoon Plain Flour\n1 clove finely chopped Garlic\n1 tsp Caraway Seed\n1/2 teaspoon Ground Cumin\nZest of 1 Lemon','step 1\nHeat the oven to 180C/160C fan/gas 4. Make the latkes by combining all of the ingredients.\n\nstep 2\nHeat the oil in a large non-stick pan. Spoon in the mixture to make six round latkes. Fry for 4-5 mins on each side, then transfer to a baking sheet and bake for 10 mins.\n\nstep 3\nCombine the yogurt and mint in a small bowl. Toss the salad leaves and tomatoes together, then serve the latkes with the mint yogurt and salad.',NULL,'https://www.youtube.com/watch?v=pRLuLYQnPiM','approved',0),
('Beef Empanadas','For the dough place lard, warm water and salt in a large kneading bowl and stir.','https://www.themealdb.com/images/media/meals/dxpc7j1764370714.jpg','Uruguayan','General','Hard',10,60,4,'60g Lard\n340g Water\n1 tsp Salt\n600g All purpose flour\n3 Tomato\n1 clove Garlic\n1 large Red Onions\nBunch Spring Onions\n750g Sirloin steak\n1 tablespoon Dried Oregano\n1 tsp Paprika\n1 tsp Red Pepper Flakes\n1 tsp Parsley\nTo taste Salt\nTo taste Pepper\n3 Egg\nSplash Egg Wash\nDrizzle Chimichurri sauce','For the dough place lard, warm water and salt in a large kneading bowl and stir. Add flour and oregano and either knead five miutes by hand or with the kneading function of your machine. Let rest covered for at least half an hour or overnight in the fridge.\n\n2\nFor the filling place tomatoes for about 30 seconds in boiling water, then cool with cold water and peel of skin and cut into cubes. Press garlic through garlic press, cut onions into cubes. Simmer garlic and onions in some olive oil until translucent. Take out onions and garlic and brown the meat at high heat from all sides. Season with all herbs and add the onions, garlic and tomatoes. Let simmer for a few minutes, add salt, pepper and additional spices to taste. You can prepare the meat the night before, chill in fridge if doing so. Boil eggs and also cut into cubes and mix with prepared meat.\n\n3\nCut dough into half and roll out one half thinnly on floured surface. Cut out circles about 12-15cm in diameter. Mine have a diameter of 12.5 cm. Place about 2-4 teaspoons of filling on one circle, put a bit of water all around the edges and fold over the other half so that you get half moons. Be sure to seal the edges with a fork. Repeat until you have no dough and filling left.\n\n4\nMeanwhile preheat oven to 200 degrees Celsius. Brush empanadas with egg wash and bake about 8 empanadas on a baking sheet lined with parchment paper for about 25min or until golden. Serve warm with chimichurri sauce.',NULL,'https://www.youtube.com/watch?v=RRNVLC6IAv4','approved',0),
('Bang bang prawn salad','step 1 Cook the noodles following pack instructions, then rinse under cold water and drain thoroughly.','https://www.themealdb.com/images/media/meals/4xcfai1763765676.jpg','Vietnamese','General','Medium',10,50,4,'140g Rice Noodles\n3 tablespoons Peanut Butter\n4 tablespoons Coconut Milk\n3  tablespoons sweet chilli sauce\n3 sliced thinly Spring Onions\n1 sliced Cucumber\n300g Bean Sprouts\n200g Prawns','step 1\nCook the noodles following pack instructions, then rinse under cold water and drain thoroughly. In a small saucepan melt together the peanut butter, coconut milk, sweet chilli sauce and half the spring onions, adding 1-2 tbsp of water to loosen the mixture to a drizzling consistency.\n\nstep 2\nMix the noodles, cucumber and beansprouts in a serving dish. Top with the prawns, drizzle over the peanut sauce and scatter over the remaining spring onions.',NULL,'https://www.youtube.com/watch?v=Na-6-lzs2wU','approved',0),
('Algerian Carrots','Place a steamer insert into a saucepan, and fill with 1 1/2 cups of water, or just below the bottom of the steamer.','https://www.themealdb.com/images/media/meals/o2cd4r1764113576.jpg','Algerian','General','Hard',15,60,6,'1 1/2 cup Water\n2 Lbs Carrots\n5 tablespoons Olive Oil\n1 tsp Salt\n1/2 teaspoon Black Pepper\n1/2 teaspoon Ground Cinnamon\n1/2 teaspoon Ground Cumin\n3 Cloves Crushed Garlic\n1/2 teaspoon Thyme\n1 Bay Leaf\n1 tsp Lemon Juice','Place a steamer insert into a saucepan, and fill with 1 1/2 cups of water, or just below the bottom of the steamer. Cover, and bring the water to a boil over high heat. Add the sliced carrots, reduce the heat to medium, and cover the pan again. Steam until tender but not mushy, 4 to 6 minutes depending on the thickness of the slices. Reserve 1/2 cup of the cooking liquid.\n\nHeat the olive oil in a skillet over medium heat. Reduce the heat to low and stir in the salt, pepper, cinnamon, cumin, garlic, and thyme. Cook the spices and garlic, stirring frequently, until fragrant, about 10 minutes. Add the 1/2 cup reserved cooking liquid and the bay leaf, cover, and simmer for 20 minutes.\n\nStir in the carrots, tossing well to coat with the spice mixture, and cook until heated through, about 2 to 3 minutes. Sprinkle with lemon juice and remove the bay leaf before serving.',NULL,'https://www.youtube.com/watch?v=mF2ND56szUQ','approved',0),
('Aussie Burgers','step 1 Make the burgers: Tip the meat into a bowl and sprinkle over 1 tsp salt and a good grinding of black pepper.Work with wet hands to mix in the seasoning.','https://www.themealdb.com/images/media/meals/44bzep1761848278.jpg','Australian','General','Easy',30,50,4,'500g Lean Minced Steak\n100g Cooked Beetroot\n2 small Naan Bread\n50g Rocket\n4 tablespoons Soured cream and chive dip','step 1\nMake the burgers: Tip the meat into a bowl and sprinkle over 1 tsp salt and a good grinding of black pepper.Work with wet hands to mix in the seasoning. Divide into four with your hands and shape into burgers. (It can be frozen at this stage.)\n\nstep 2\nSort out your ingredients: Slice the beetroot and split the naan breads.\n\nstep 3\nToast the naans: Heat a griddle pan or barbecue. Griddle the naans on both sides until lightly toasted and set aside. Add the burgers to the grill or barbecue and cook for 2-3 minutes, then turn and cook the other side for a further 2-3 minutes.\n\nstep 4\nAssemble the dish: Set half a toasted naan on each serving plate and put a pile of rocket on each. Top with a burger, then a few slices of beetroot and a dollop of soured cream. Sprinkle with salt and freshly ground black pepper and serve immediately with a big green salad and chips. A glass of red wine wouldn’t go amiss, either.',NULL,'https://www.youtube.com/watch?v=pSupybydA_U','approved',0),
('Breakfast Potatoes','Before you do anything, freeze your bacon slices that way when you\'re ready to prep, it\'ll be so much easier to chop!','https://www.themealdb.com/images/media/meals/1550441882.jpg','Canadian','General','Medium',20,40,4,'3 Medium Potatoes\n1 tbs Olive Oil\n2 strips Bacon\nMinced Garlic Clove\n1 tbs Maple Syrup\nGarnish Parsley\nPinch Salt\nPinch Pepper\nTo taste Allspice','Before you do anything, freeze your bacon slices that way when you\'re ready to prep, it\'ll be so much easier to chop!\nWash the potatoes and cut medium dice into square pieces. To prevent any browning, place the already cut potatoes in a bowl filled with water.\nIn the meantime, heat 1-2 tablespoons of oil in a large skillet over medium-high heat. Tilt the skillet so the oil spreads evenly.\nOnce the oil is hot, drain the potatoes and add to the skillet. Season with salt, pepper, and Old Bay as needed.\nCook for 10 minutes, stirring the potatoes often, until brown. If needed, add a tablespoon more of oil.\nChop up the bacon and add to the potatoes. The bacon will start to render and the fat will begin to further cook the potatoes. Toss it up a bit! The bacon will take 5-6 minutes to crisp.\nOnce the bacon is cooked, reduce the heat to medium-low, add the minced garlic and toss. Season once more. Add dried or fresh parsley. Control heat as needed.\nLet the garlic cook until fragrant, about one minute.\nJust before serving, drizzle over the maple syrup and toss. Let that cook another minute, giving the potatoes a caramelized effect.\nServe in a warm bowl with a sunny side up egg!',NULL,'https://www.youtube.com/watch?v=BoD0TIO9nE4','approved',0),
('Beef and Broccoli Stir-Fry','Marinate the beef: Stir together the beef marinade ingredients (1 teaspoon soy sauce, 1 teaspoon Chinese rice wine, 1/2 teaspoon cornstarch, 1/8 teaspoon black pepper) in a medium bowl.','https://www.themealdb.com/images/media/meals/m0p0j81765568742.jpg','Chinese','General','Hard',15,60,4,'1 tsp Soy Sauce\n1 tsp Dry sherry\n1/2 tsp Cornstarch\n1/8 teaspoon Black Pepper\n1 lb Sirloin steak\n2 tablespoons Oyster Sauce\n1 tsp Dry sherry\n1 tablespoon Soy Sauce\n1/4 cup Chicken Stock\n1 lb Broccoli\n2 tablespoons High Heat Cooking Oil\n2 cloves minced Garlic\n1 tsp Cornstarch\n1 tablespoon Water','Marinate the beef:\nStir together the beef marinade ingredients (1 teaspoon soy sauce, 1 teaspoon Chinese rice wine, 1/2 teaspoon cornstarch, 1/8 teaspoon black pepper) in a medium bowl.\n\nAdd the beef slices and stir until coated. Let stand for 10 minutes.\n\nPrepare the sauce:\nStir together the sauce ingredients (2 tablespoons oyster sauce, 1 teaspoon Chinese rice wine, 1 teaspoon soy sauce, 1/4 cup chicken broth) in a small bowl. Set aside.\n\nBlanch or steam the broccoli:\nBring a pot of water to a boil. Add the broccoli and cook until crisp-tender, about 2 minutes. Drain thoroughly.\n\nStir-fry the beef:\nHeat a large frying pan or wok over high heat until a bead of water sizzles and instantly evaporates upon contact. Add the cooking oil and swirl to coat.\n\nAdd the beef and immediately spread it out all over the surface of the wok or pan in a single layer (preferably not touching).\n\nLet the beef fry undisturbed for 1 minute. Flip the beef slices over, add the garlic to the pan, and fry for an additional 30 seconds to 1 minute until no longer pink.\n\nAdd the sauce, cornstarch, and broccoli:\nPour in the sauce and the cornstarch slurry (1 teaspoon cornstarch dissolved in 1 tablespoon of water). Stir until the sauce boils and thickens, about 30 seconds. Stir in the broccoli.\n\nServe immediately, with steamed rice or on its own.',NULL,'https://www.youtube.com/watch?v=BBABeZjlRM8','approved',0),
('Cevapi Sausages','Place the ground meat in a bowl.','https://www.themealdb.com/images/media/meals/vc08jn1628769553.jpg','Croatian','General','Hard',20,30,4,'500g Minced Beef\n250g Minced Pork\n1 Onion\n4 cloves Garlic\n3 tblsp chopped Parsley\n1 tbs Paprika\n3/4 teaspoon Baking Powder\n2 tbs Breadcrumbs\n3 tbs Water\n1 Vegetable Stock Cube\n1 tsp Salt\n1 tsp Pepper','Place the ground meat in a bowl. Chop the onion very finely and grate the garlic cloves. Add to the bowl. Add the chopped parsley, all sorts of paprika, baking soda, dried breadcrumbs, water, Vegeta, salt, and pepper.\nMix well with the hand mixer fitted with the dough hooks. Cover the bowl with cling film/ plastic foil and leave to rest for 1 or 2 hours in the refrigerator.\nTake portions of the meat mixture, about 50-55 g/ 1.7-1.9 oz/ ¼ cup portions, and form the cevapi. The rolls should be about as thick as your thumb and about 7-10 cm/ 3-4 inches long. I had 18 sausages. The recipe can be easily doubled.\nGrill the cevapcici on the hot grill pan or on the barbecue for about 12-14 minutes, turning them several times in between, or until brown and cooked through. I checked by cutting one in the middle and then grilling the following batches for the same period of time.\nServe hot as suggested above. The cevapcici can be reheated in the oven at 180 degrees Celsius/ 350 degrees Fahrenheit for about 10 minutes or until heated through. Check one, if it is not hot enough, give the sausages a few more minutes.',NULL,'https://www.youtube.com/watch?v=_MpSxSgS7f8','approved',0),
('Feteer Meshaltet','Mix the flour and salt then pour one cup of water and start kneading.','https://www.themealdb.com/images/media/meals/9f4z6v1598734293.jpg','Egyptian','General','Easy',15,60,6,'4 cups Flour\n1 1/2 cups Water\n1/4 tsp Salt\n1 cup Unsalted Butter\n1/4 cup Olive Oil','Mix the flour and salt then pour one cup of water and start kneading.\nIf you feel the dough is still not coming together or too dry, gradually add the remaining water until you get a dough that is very elastic so that when you pull it and it won’t be torn.\nLet the dough rest for just 10 minutes then divide the dough into 6-8 balls depending on the size you want for your feteer.\nWarm up the butter/ghee or oil you are using and pour into a deep bowl.\nImmerse the dough balls into the warm butter. Let it rest for 15 to 20 minutes.\nPreheat oven to 550F.\nStretch the first ball with your hands on a clean countertop. Stretch it as thin as you can, the goal here is to see your countertop through the dough.\nFold the dough over itself to form a square brushing in between folds with the butter mixture.\nSet aside and start making the next ball.\nStretch the second one thin as we have done for the first ball.\nPlace the previous one on the middle seam side down. Fold the outer one over brushing with more butter mixture as you fold. Set aside.\nKeep doing this for the third and fourth balls. Now we have one ready, place on a 10 inch baking/pie dish seam side down and brush the top with more butter.\nRepeat for the remaining 4 balls to make a second one. With your hands lightly press the folded feteer to spread it on the baking dish.\nPlace in preheated oven for 10 minutes when the feteer starts puffing turn on the broiler to brown the top.\nWhen it is done add little butter on top and cover so it won’t get dry.',NULL,'https://www.youtube.com/watch?v=-mW1unsVhFU','approved',0),
('Beef Caldereta','0. Heat oil in a cooking pot. Saute onion and garlic until onion softens 1.','https://www.themealdb.com/images/media/meals/41cxjh1683207682.jpg','Filipino','General','Hard',5,40,4,'2kg cut cubes Beef\n1 Beef Stock\n1 tbs Soy Sauce\n2 cups Water\n1 sliced Green Pepper\n1 sliced Red Pepper\n1 sliced Potatoes\n1 sliced Carrots\n8 ounces Tomato Puree\n3  tablespoons Peanut Butter\n5 Chilli Powder\n1 chopped Onion\n5 cloves Garlic\n3 tbs Olive Oil','0.\tHeat oil in a cooking pot. Saute onion and garlic until onion softens\n1.\tAdd beef. Saute until the outer part turns light brown.\n2.\tAdd soy sauce. Pour tomato sauce and water. Let boil.\n3.\tAdd Knorr Beef Cube. Cover the pressure cooker. Cook for 30 minutes.\n4.\tPan-fry carrot and potato until it browns. Set aside.\n5.\tAdd chili pepper, liver spread and peanut butter. Stir.\n6.\tAdd bell peppers, fried potato and carrot. Cover the pot. Continue cooking for 5 to 7 minutes.\n7.\tSeason with salt and ground black pepper. Serve.',NULL,'https://www.youtube.com/watch?v=yI7hTz0ft5k','approved',0),
('Garides Saganaki','Place the prawns in a pot and add enough water to cover.','https://www.themealdb.com/images/media/meals/wuvryu1468232995.jpg','Greek','General','Medium',5,60,4,'500g Raw king prawns\n3 tablespoons Olive oil\n1 Chopped onion\npinch Freshly chopped parsley\n250ml White wine\n1 (400g) tin Chopped tomatoes\n1/2 teaspoon Minced garlic\n1 (200g) pack Cubed Feta cheese','Place the prawns in a pot and add enough water to cover. Boil for 5 minutes. Drain, reserving the liquid, and set aside.\nHeat 2 tablespoons of oil in a saucepan. Add the onion; cook and stir until soft. Mix in the parsley, wine, tomatoes, garlic and remaining olive oil. Simmer, stirring occasionally, for about 30 minutes, or until the sauce is thickened.\nWhile the sauce is simmering, the prawns should become cool enough to handle. First remove the legs by pinching them, and then pull off the shells, leaving the head and tail on.\nWhen the sauce has thickened, stir in the prawns. Bring to a simmer again if the sauce has cooled with the prawns, and cook for about 5 minutes. Add the feta and remove from the heat. Let stand until the cheese starts to melt. Serve warm with slices of crusty bread.\nThough completely untraditional, you can add a few tablespoons of stock or passata to this recipe to make a delicious pasta sauce. Toss with pasta after adding the feta, and serve.',NULL,'https://www.youtube.com/watch?v=uO0ejc85zSE','approved',0),
('Coddled pork with cider','STEP 1 Heat the butter in a casserole dish until sizzling, then fry the pork for 2-3 mins on each side until browned.','https://www.themealdb.com/images/media/meals/7vpsfp1608588991.jpg','Irish','General','Medium',20,60,4,'Knob Butter\n2 Pork Chops\n4 Bacon\n2 Potatoes\n1 Carrots\n1/2 Swede\n1/2 Cabbage\n1 Bay Leaf\n100ml Cider\n100g Chicken Stock','STEP 1\nHeat the butter in a casserole dish until sizzling, then fry the pork for 2-3 mins on each side until browned. Remove from the pan.\n\nSTEP 2\nTip the bacon, carrot, potatoes and swede into the pan, then gently fry until slightly coloured. Stir in the cabbage, sit the chops back on top, add the bay leaf, then pour over the cider and stock. Cover the pan, then leave everything to gently simmer for 20 mins until the pork is cooked through and the vegetables are tender.\n\nSTEP 3\nServe at the table spooned straight from the dish.',NULL,'https://www.youtube.com/watch?v=ftn_4mc-65o','approved',0),
('Chicken Alfredo Primavera','Heat 1 tablespoon of butter and 2 tablespoons of olive oil in a large skillet over medium-high heat.','https://www.themealdb.com/images/media/meals/syqypv1486981727.jpg','Italian','General','Hard',15,30,4,'2 tablespoons Butter\n3 tablespoons Olive Oil\n5 boneless Chicken\n1 teaspoon Salt\n1 cut into 1/2-inch cubes Squash\n1 Head chopped Broccoli\n8-ounce sliced mushrooms\n1 red Pepper\n1 chopped onion\n3 cloves garlic\n1/2 teaspoon red pepper flakes\n1/2 cup white wine\n1/2 cup milk\n1/2 cup heavy cream\n1 cup grated Parmesan cheese\n16 ounces bowtie pasta\npinch Salt\npinch Pepper\nchopped Parsley','Heat 1 tablespoon of butter and 2 tablespoons of olive oil in a large skillet over medium-high heat. Season both sides of each chicken breast with seasoned salt and a pinch of pepper. Add the chicken to the skillet and cook for 5-7 minutes on each side, or until cooked through.  While the chicken is cooking, bring a large pot of water to a boil. Season the boiling water with a few generous pinches of kosher salt. Add the pasta and give it a stir. Cook, stirring occasionally, until al dente, about 12 minutes. Reserve 1/2 cup of  pasta water before draining the pasta.  Remove the chicken from the pan and transfer it to a cutting board; allow it to rest. Turn the heat down to medium and dd the remaining 1 tablespoon of butter and olive oil to the same pan you used to cook the chicken. Add the veggies (minus the garlic) and red pepper flakes to the pan and stir to coat with the oil and butter (refrain from seasoning with salt until the veggies are finished browning). Cook, stirring often, until the veggies are tender, about 5 minutes. Add the garlic and a generous pinch of salt and pepper to the pan and cook for 1 minute.  Deglaze the pan with the white wine. Continue to cook until the wine has reduced by half, about 3 minutes. Stir in the milk, heavy cream, and reserved pasta water. Bring the mixture to a gentle boil and allow to simmer and reduce for 2-3 minutes. Turn off the heat and add the Parmesan cheese and cooked pasta. Season with salt and pepper to taste. Garnish with Parmesan cheese and chopped parsley, if desired.',NULL,'https://www.youtube.com/watch?v=qCIbq8HywpQ','approved',0),
('Callaloo and SaltFish','Soak salted fish in water overnight.','https://www.themealdb.com/images/media/meals/73o3vq1765317873.jpg','Jamaican','General','Medium',20,10,6,'1/2 lb Salt Cod\n4 Bacon\n525g Callaloo\n1 chopped Onion\n2 chopped Spring Onions\n2 cloves minced Garlic\n1 chopped Scotch Bonnet\n2 chopped Plum Tomatoes\n2 sprigs Thyme\n1/4 tsp Black Pepper','Soak salted fish in water overnight. Next, heat salted fish in water on stove until water boils. You should see a foam on top. Remove from heat and drain. Set aside and shred salted fish once it cools.\nCook bacon in skillet over medium heat until crispy. Remove bacon from heat and drain the majority of the bacon grease, leaving about 1 tablespoon in the skillet. \nAdd yellow onion, green onion, scotch bonnet pepper, and garlic to the skillet and stir. Cook for about 2 minutes or until onions soften. Add salted fish to skillet and stir. Cook for about a minute. \nNext, add callaloo, roma tomatoes, thyme, and black pepper. Stir to combine and cook until heated through, about 2 minutes.\nEnjoy',NULL,'https://www.youtube.com/watch?v=n1fRCk-zTRM','approved',0),
('Honey Teriyaki Salmon','Mix all the ingredients in the Honey Teriyaki Glaze together.','https://www.themealdb.com/images/media/meals/xxyupu1468262513.jpg','Japanese','General','Easy',20,10,4,'1 lb Salmon\n1 tablespoon Olive oil\n2 tablespoons Soy Sauce\n2 tablespoons Sake\n4 tablespoons Sesame Seed','Mix all the ingredients in the Honey Teriyaki Glaze together. Whisk to blend well. Combine the salmon and the Glaze together.\n\nHeat up a skillet on medium-low heat. Add the oil, Pan-fry the salmon on both sides until it’s completely cooked inside and the glaze thickens.\n\nGarnish with sesame and serve immediately.',NULL,'https://www.youtube.com/watch?v=4MpYuaJsvRw','approved',0),
('Kenyan Beef Curry','Bring the 4 cups of water to a boil in a Dutch oven or soup pot.','https://www.themealdb.com/images/media/meals/lqampv1762325397.jpg','Kenyan','General','Hard',5,40,4,'4 cups Water\n2 Lbs Sirloin Steak tips\n4 Garlic Clove\n2 teaspoons Ground Ginger\n2 tblsp Oil\n2 medium Red Onions\n4 Tomato\n2 tblsp Paprika\n1/2 teaspoon Black Pepper\n2 teaspoons Curry Powder\n4 tablespoons Tomato Puree\nDash Salt\n1 Chilli\nLeaves Cilantro','Bring the 4 cups of water to a boil in a Dutch oven or soup pot. Add the beef, garlic, and ginger, and stir well. Bring to a gentle simmer, cover, and cook, stirring occasionally, for 20 minutes. If you get any foamy scum on the top, not to worry, simply spoon it away or stir it back in.\nRemove from the heat, and drain, but reserve the excess water for later.\nReturn the pot or Dutch oven to medium heat with the 2 tablespoons of cooking oil. Once the oil is shimmering, add the onions and cook, stirring occasionally, until softened, 5 to 7 minutes.\nAdd the tomatoes to the onions, and continue cooking, stirring occasionally, until the tomatoes are falling apart, 3 to 5 minutes.\nAdd the drained beef to the tomato and onion mixture, and stir well. Continue cooking over medium heat for 5 minutes, stirring occasionally.\nAdd the paprika, pepper, curry powder, tomato paste, and salt to taste, and stir well.\nAdd back the excess water that was used for cooking the beef, along with enough extra water to cover. Bring to a boil, reduce heat, and simmer, uncovered, stirring occasionally, for about 1 hour, or until the meat is tender and the sauce is thickened. Add additional water if your beef curry begins to dry and stick, or if would like your curry to have more of a soupy consistency.\nWhen the beef curry is ready, remove from the heat, give it a taste, and adjust the seasonings as desired. Garnish with fresh chilis and cilantro.',NULL,'https://www.youtube.com/watch?v=NxrOueTLiqA','approved',0),
('Ayam Percik','In a blender, add the ingredients for the spice paste and blend until smooth.','https://www.themealdb.com/images/media/meals/020z181619788503.jpg','Malaysian','General','Hard',25,50,4,'6 Chicken Thighs\n16 Challots\n1 1/2 Ginger\n6 Garlic Clove\n8 Cayenne Pepper\n2 tbs Turmeric\n1 1/2 Cumin\n1 1/2 Coriander\n1 1/2 Fennel\n2 tbs Tamarind Paste\n1 can Coconut Milk\n1 tsp Sugar\n1 cup Water','In a blender, add the ingredients for the spice paste and blend until smooth.\nOver medium heat, pour the spice paste in a skillet or pan and fry for 10 minutes until fragrant. Add water or oil 1 tablespoon at a time if the paste becomes too dry. Don\'t burn the paste. Lower the fire slightly if needed.\nAdd the cloves, cardamom, tamarind pulp, coconut milk, water, sugar and salt. Turn the heat up and bring the mixture to boil. Turn the heat to medium low and simmer for 10 minutes. Stir occasionally. It will reduce slightly. This is the marinade/sauce, so taste and adjust seasoning if necessary. Don\'t worry if it\'s slightly bitter. It will go away when roasting.\nWhen the marinade/sauce has cooled, pour everything over the chicken and marinate overnight to two days.\nPreheat the oven to 425 F.\nRemove the chicken from the marinade. Spoon the marinade onto a greased (or aluminum lined) baking sheet. Lay the chicken on top of the sauce (make sure the chicken covers the sauce and the sauce isn\'t exposed or it\'ll burn) and spread the remaining marinade on the chicken. Roast for 35-45 minutes or until internal temp of the thickest part of chicken is at least 175 F.\nLet chicken rest for 5 minutes. Brush the chicken with some of the oil. Serve chicken with the sauce over steamed rice (or coconut rice).',NULL,'https://www.youtube.com/watch?v=9ytR28QK6I8','approved',0),
('Cajun spiced fish tacos','Cooking in a cajun spice and cayenne pepper marinade makes this fish super succulent and flavoursome.','https://www.themealdb.com/images/media/meals/uvuyxu1503067369.jpg','Mexican','General','Hard',10,50,4,'2 tbsp cajun\n1 tsp cayenne pepper\n4 fillets white fish\n1 tsp vegetable oil\n8 flour tortilla\n1 sliced avocado\n2 shredded little gem lettuce\n4 shredded Spring Onions\n1 x 300ml salsa\n1 pot sour cream\n1 lemon\n1 clove finely chopped garlic','Cooking in a cajun spice and cayenne pepper marinade makes this fish super succulent and flavoursome. Top with a zesty dressing and serve in a tortilla for a quick, fuss-free main that\'s delightfully summery.\n\nOn a large plate, mix the cajun spice and cayenne pepper with a little seasoning and use to coat the fish all over.\n\nHeat a little oil in a frying pan, add in the fish and cook over a medium heat until golden. Reduce the heat and continue frying until the fish is cooked through, about 10 minutes. Cook in batches if you don’t have enough room in the pan.\n\nMeanwhile, prepare the dressing by combining all the ingredients with a little seasoning.\nSoften the tortillas by heating in the microwave for 5-10 seconds. Pile high with the avocado, lettuce and spring onion, add a spoonful of salsa, top with large flakes of fish and drizzle over the dressing.',NULL,'https://www.youtube.com/watch?v=N4EdUt0Ou48','approved',0),
('Lamb Tagine','Heat the olive oil in a heavy-based pan and add the onion and carrot.','https://www.themealdb.com/images/media/meals/yuwtuu1511295751.jpg','Moroccan','General','Hard',10,10,4,'2 tblsp Olive Oil\n1 finely sliced Onion\n2 chopped Carrots\n500g Lamb Leg\n2 cloves minced Garlic\n½ tsp Cumin\n½ tsp Ginger\n¼ tsp Saffron\n1 tsp Cinnamon\n1 tblsp Honey\n100g Apricot\n1 Vegetable Stock Cube\n1 medium chopped Butternut Squash\nSteamed Couscous\nChopped Parsley','Heat the olive oil in a heavy-based pan and add the onion and carrot. Cook for 3- 4 mins until softened.\n\nAdd the diced lamb and brown all over. Stir in the garlic and all the spices and cook for a few mins more or until the aromas are released.\n\nAdd the honey and apricots, crumble in the stock cube and pour over roughly 500ml boiling water or enough to cover the meat. Give it a good stir and bring to the boil. Turn down to a simmer, put the lid on and cook for 1 hour.\n\nRemove the lid and cook for a further 30 mins, then stir in the squash. Cook for 20 – 30 mins more until the squash is soft and the lamb is tender. Serve alongside rice or couscous and sprinkle with parsley and pine nuts, if using.',NULL,'https://www.youtube.com/watch?v=bR5Cqu84S_k','approved',0),
('Bigos (Hunters Stew)','Preheat the oven to 350 degrees F (175 degrees C).','https://www.themealdb.com/images/media/meals/md8w601593348504.jpg','Polish','General','Hard',15,10,4,'2 sliced Bacon\n1 lb Kielbasa\n1 lb Pork\n1/4 cup Flour\n3 chopped Garlic\n1 Diced Onion\n1 1/2 cup Mushrooms\n4 cups Cabbage\n1 Jar Sauerkraut\n1/4 cup Red Wine\n1 Bay Leaf\n1 tsp Basil\n1 tsp Marjoram\n1 tbs Paprika\n1/8 teaspoon Caraway Seed\n1 dash Hotsauce\n5 Cups Beef Stock\n2 tbs Tomato Puree\n1 cup Diced Tomatoes\n1 dash Worcestershire Sauce','Preheat the oven to 350 degrees F (175 degrees C).\n\nHeat a large pot over medium heat. Add the bacon and kielbasa; cook and stir until the bacon has rendered its fat and sausage is lightly browned. Use a slotted spoon to remove the meat and transfer to a large casserole or Dutch oven.\n\nCoat the cubes of pork lightly with flour and fry them in the bacon drippings over medium-high heat until golden brown. Use a slotted spoon to transfer the pork to the casserole. Add the garlic, onion, carrots, fresh mushrooms, cabbage and sauerkraut. Reduce heat to medium; cook and stir until the carrots are soft, about 10 minutes. Do not let the vegetables brown.\n\nDeglaze the pan by pouring in the red wine and stirring to loosen all of the bits of food and flour that are stuck to the bottom. Season with the bay leaf, basil, marjoram, paprika, salt, pepper, caraway seeds and cayenne pepper; cook for 1 minute.\n\nMix in the dried mushrooms, hot pepper sauce, Worcestershire sauce, beef stock, tomato paste and tomatoes. Heat through just until boiling. Pour the vegetables and all of the liquid into the casserole dish with the meat. Cover with a lid.\n\nBake in the preheated oven for 2 1/2 to 3 hours, until meat is very tender.',NULL,'https://www.youtube.com/watch?v=Oqg_cO4s8ik','approved',0),
('Grilled Portuguese sardines','STEP 1 Put all of the ingredients, except the sardines, into a bowl and mix together with some seasoning.','https://www.themealdb.com/images/media/meals/lpd4wy1614347943.jpg','Portuguese','General','Medium',10,30,4,'8 Sardines\n2 tbs Olive Oil\n3 cloves Garlic\n1 tbs Paprika\n1/2 Lemon\n4 sprigs Rosemary\n1 Red Chilli','STEP 1\n\nPut all of the ingredients, except the sardines, into a bowl and mix together with some seasoning. Pour into a baking dish, add the sardines and toss really well. Cover and chill for a few hours.\n\nSTEP 2\n\nHeat a BBQ or griddle pan until hot. Cook the sardines for 4-5 minutes on each side or until really caramelised and charred. Put onto a serving plate, drizzle with oil, sprinkle with a little more paprika and squeeze over the lemon wedges.',NULL,'https://www.youtube.com/watch?v=JYtMjKa6cdY','approved',0),
('Blini Pancakes','In a large bowl, whisk together 1/2 cup buckwheat flour, 2/3 cup all-purpose flour, 1/2 teaspoon salt, and 1 teaspoon yeast.','https://www.themealdb.com/images/media/meals/0206h11699013358.jpg','Russian','General','Medium',25,70,6,'1/2 cup Buckwheat\n2/3 Cup Flour\n1/2 tsp Salt\n1 tsp Yeast\n1 cup Milk\n2 tbs Butter\n1 Seperated Egg','In a large bowl, whisk together 1/2 cup buckwheat flour, 2/3 cup all-purpose flour, 1/2 teaspoon salt, and 1 teaspoon yeast.\n\nMake a well in the center and pour in 1 cup warm milk, whisking until the batter is smooth.\n\nCover the bowl and let the batter rise until doubled, about 1 hour.\n\nEnrich and Rest the Batter\nStir 2 tablespoons melted butter and 1 egg yolk into the batter.\n\nIn a separate bowl, whisk 1 egg white until stiff, but not dry.\n\nFold the whisked egg white into the batter.\n\nCover the bowl and let the batter stand 20 minutes.\n\nPan-Fry the Blini\nHeat butter in a large nonstick skillet over medium heat.\n\nDrop quarter-sized dollops of batter into the pan, being careful not to overcrowd the pan. Cook for about 1 minute or until bubbles form.\n\nTurn and cook for about 30 additional seconds.\n\nRemove the finished blini onto a plate and cover them with a clean kitchen towel to keep warm. Add more butter to the pan and repeat the frying process with the remaining batter.',NULL,'https://www.youtube.com/watch?v=GsB8ZI5vREA','approved',0),
('Ajo blanco','step 1 Tip the bread into a bowl and pour over 350ml water.','https://www.themealdb.com/images/media/meals/5jdtie1763289302.jpg','Spanish','General','Easy',20,50,4,'150g White bread\n200g Almonds\n50 ml Extra Virgin Olive Oil\n1 Garlic Clove\n1 ½ tbsp Red Wine Vinegar','step 1\nTip the bread into a bowl and pour over 350ml water. Leave to soak for 10 mins.\n\nstep 2\nBlend the ingredients together with 350ml water and 1 tsp salt.\n\nstep 3\nLet the soup cool in the fridge for 1 hr or so, then serve with a drizzle of oil and some black pepper.',NULL,'https://www.youtube.com/watch?v=AS2mSRtWyW0','approved',0),
('Falafel Pita Sandwich with Tahini Sauce','Preheat the oven to 450 degrees F (230 degrees C).','https://www.themealdb.com/images/media/meals/ae6clc1760524712.jpg','Syrian','Vegetarian','Hard',20,40,4,'12 Falafel\n1/4 cup Tahini\n1/4 cup Water\n2 tablespoons Lemon Juice\n2 cloves Garlic\n1/4 tsp Paprika\n6 Pita Bread\n1 Lettuce\n1 Tomato\n1/2 Cucumber\n1 Dill Pickles\n1/4 Red Onions\n3 tsp Harissa Spice','Preheat the oven to 450 degrees F (230 degrees C). Place falafel on a baking sheet.\n\nBake in the preheated oven until heated through, 8 to 10 minutes.\n\nWhile falafel bake, whisk tahini, water, lemon juice, garlic, and paprika together in a bowl.\n\nCut about 1 inch from the top of each pita to form a pocket. Add 2 falafel to each pita with equal amounts lettuce, tomato, cucumber, pickle, and red onion. Drizzle each with about 1 tablespoon tahini sauce and some harissa.',NULL,'https://www.youtube.com/watch?v=wt8nApxP5fE','approved',0),
('Chakchouka','In a large cast iron skillet or sauté pan with a lid, heat oil over medium high heat.','https://www.themealdb.com/images/media/meals/gpz67p1560458984.jpg','Tunisian','General','Hard',10,10,4,'4 Tomatoes\n2 tbs Olive Oil\n1 Diced Onion\n1 sliced Red Pepper\n1 sliced Green Pepper\n3 Cloves Crushed Garlic\n1 tsp Cumin\n1 tsp Paprika\n3/4 teaspoon Salt\n1/2 teaspoon Chili Powder\n4 Eggs','In a large cast iron skillet or sauté pan with a lid, heat oil over medium high heat. Add the onion and sauté for 2-3 minutes, until softened. Add the peppers and garlic, and sauté for an additional 3-5 minutes. Add the tomatoes, cumin, paprika, salt, and chili powder. Mix well and bring the mixture to a simmer. Reduce the heat to medium low and continue to simmer, uncovered, 10-15 minutes until the mixture has thickened to your desired consistency. (Taste the sauce at this point and adjust for salt and spice, as desired.) Using the back of a spoon, make four craters in the mixture, large enough to hold an egg. Crack one egg into each of the craters. Cover the skillet and simmer for 5-7 minutes, until the eggs have set. Serve immediately with crusty bread or pita.',NULL,'https://www.youtube.com/watch?v=EHKNu93MSx4','approved',0),
('Beetroot pancakes','step 1 Put the beetroot in a jug with the milk and blend with a stick blender until smooth.','https://www.themealdb.com/images/media/meals/xlqqhw1764369924.jpg','Ukrainian','General','Hard',5,50,8,'3 Beetroot\n50 ml Milk\n200g Self-raising Flour\n1 tsp Baking Powder\n2 tablespoons Maple Syrup\n1/2 teaspoon Vanilla Extract\n3 Egg\n25g Butter\n200g Frozen Mixed Berries\n2 tablespoons Blackcurrant Jam\n100g Greek Yogurt','step 1\nPut the beetroot in a jug with the milk and blend with a stick blender until smooth. Pour into a bowl with the rest of the pancake ingredients and whisk until smooth and vibrant purple.\n\nstep 2\nPut a small knob of butter in a large non-stick frying pan and heat over a medium-low heat until melted and foamy. Now create 3 or 4 pancakes each made from 2 tbsp of the batter. Cook for 2-3 mins then flip over and cook for a further minute until cooked through. Repeat with any remaining batter. Heat oven to lowest setting and keep the pancakes warm in there until needed.\n\nstep 3\nServe with your favourite pancake toppings or make a simple compote by simmering frozen berries in with 1 tbsp blackcurrant jam until bubbling and syrupy (about 5-10 mins). In a small bowl stir together the remaining jam and the yogurt. Stack the cooked pancakes with the yogurt and pour the warm berry compote over the top.',NULL,'https://www.youtube.com/watch?v=HzQT0rHKCWM','approved',0),
('Chivito sandwich','For the brioche buns heat the milk with the butter and molasses until the butter has melted.','https://www.themealdb.com/images/media/meals/j80gmw1764372176.jpg','Uruguayan','General','Hard',20,10,4,'80g Milk\n60g Butter\n1 tablespoon Molasses\n220g Water\n9 Egg\n500g Bread Flour\n10g Salt\n10g Yeast\nSplash Egg Wash\nSprinkling Sesame Seed\n4 Onion\n8 Sirloin steak\nTo serve Garlic\n8 Bacon\n8 slices Ham\n8 slices Mozzarella\n4 Tomato\n1/4 Lettuce\nTo serve Mustard\nTo serve Chimichurri sauce','For the brioche buns heat the milk with the butter and molasses until the butter has melted. Add the cold water and egg to this mix.\n\n2\nIn a large bowl place flour, salt and yeast and mix. Then add the milk and water mix and stir with a wooden spoon until combined. You don\'t have to knead the dough, it is perfectly fine to do this by hand with a wooden spoon, this doesn\'t need to be very thorough. Cover with a damp towel and stick in the fridge overnight.\n\n3\nThe next morning knead dough on a generously floured surface for a little and cut into eight equal pieces. Shape these into balls and place on a baking sheet lined with parchment paper. Cover again with damp towel and let rise for about an hour or until double in size.\n\n4\nHeat oven to 220 degrees Celsius. Brush the buns with either milk, heavy cream or egg wash and sprinkle with sesame seeds, if desired. Bake for about 15-20min or until golden. Let cool.\n\n5\nFor the toppings chop the onions and sauté in a bit of butter, let caramelize, this may take ten to 15 minutes, stir occasionally. Rub the steaks with a bit of garlic and then grill or fry the steaks, the bacon, and eggs with salt and pepper, toast the buns after having cut in half. Spread mustard on one bun half, layer each chivito with steak, a slice of ham, a slice of cheese, one bacon stripe, a tomato slice, and some lettuce. Place fried egg on top and sprinkle generously with chimichurri and some onions right before serving.',NULL,'https://www.youtube.com/watch?v=tX3fN9AG_ik','approved',0),
('Barbecue pork buns','step 1 Heat the oven to 200C/fan 180C/gas.','https://www.themealdb.com/images/media/meals/tzsy461763769901.jpg','Vietnamese','General','Medium',25,10,4,'85g Sugar\n500g White Bread Mix\n1 tablespoon Sunflower Oil\n12 Bacon\nKnob Ginger\n2 cloves chopped Garlic\n2 tablespoons Soy Sauce\n3  tablespoons Clear Honey\n3  tablespoons Tomato Puree\n1 beaten Egg','step 1\nHeat the oven to 200C/fan 180C/gas. Mix the sugar into the bread mix in a large bowl, then add water as instructed on the pack. Bring the dough together with a wooden spoon, then knead on a lightly floured surface for 5 mins until smooth. Put into a large bowl, cover with oiled cling film then leave in a warm place until doubled in size.\n\nstep 2\nMeanwhile, heat the oil in a pan, then fry the bacon until crisp, about 5 mins. Add the ginger and garlic and fry for 1 min until soft, then tip in the soy, honey and tomato purée and stir well. Can be made up to 3 days ahead.\n\nstep 3\nTurn out the dough and knead briefly, then pull into 12 even-sized balls. Flatten with your hands, then put a teaspoon-size blob of the filling in the middle. Draw the dough up and pinch it closed like a purse, then turn the bun over and sit it on a large baking sheet. Cover with oiled cling film and leave to rise for about 30 mins until the dough feels pillowy. Brush with egg and bake for 20 mins until golden. Serve warm with dipping sauce. Can be frozen after second rise for up to 1 month or baked up to a day ahead and re-warmed.',NULL,'https://www.youtube.com/watch?v=T3mBULRIcY8','approved',0),
('Algerian Flafla (Bell Pepper Salad)','Preheat an oven to 450 degrees F (230 degrees C).','https://www.themealdb.com/images/media/meals/tbj1bs1764118062.jpg','Algerian','Vegetarian','Medium',15,50,4,'3 Green Pepper\n1 tablespoon Olive Oil\n1 tablespoon chopped Red Onions\n1 clove peeled crushed Garlic\nTo taste Salt\nTo taste Pepper\n1 Diced Plum Tomatoes','Preheat an oven to 450 degrees F (230 degrees C). Place the whole peppers on aluminum foil. Bake until the skin is spotted black and the peppers are soft, 30 to 45 minutes, turning the peppers once if necessary.\n\nRemove peppers from the oven and set aside to cool for 10 minutes. Peel off the skin and remove the stem and seeds. Chop the roasted peppers into half-inch pieces.\n\nHeat the olive oil in a skillet over medium heat. Stir in the onion and cook, stirring frequently, until the onion has softened and turned translucent, about 5 minutes. Add the garlic, salt, and pepper; stir in the chopped peppers and tomato. Cook over medium heat, stirring occasionally, until the tomato is soft and the mixture is well incorporated, about 5 minutes.',NULL,'https://www.youtube.com/watch?v=JXrS1doDnNg','approved',0),
('Canadian Butter Tarts','Preheat the oven to fan 170C/ conventional 190C/gas 5.','https://www.themealdb.com/images/media/meals/wpputp1511812960.jpg','Canadian','General','Medium',20,40,8,'375g Shortcrust Pastry\n2 large Eggs\n175g Muscovado Sugar\n100g Raisins\n1 tsp Vanilla Extract\n50g Butter\n4 tsp Single Cream\n50g Walnuts','Preheat the oven to fan 170C/ conventional 190C/gas 5. Roll out the pastry on a lightly floured surface so it’s slightly thinner than straight from the pack. Then cut out 18-20 rounds with a 7.5cm fluted cutter, re-rolling the trimmings. Use the rounds to line two deep 12-hole tart tins (not muffin tins). If you only have a regular-sized, 12-hole tart tin you will be able to make a few more slightly shallower tarts.\nBeat the eggs in a large bowl and combine with the rest of the ingredients except the walnuts. Tip this mixture into a pan and stir continuously for 3-4 minutes until the butter melts, and the mixture bubbles and starts to thicken. It should be thick enough to coat the back of a wooden spoon. Don’t overcook, and be sure to stir all the time as the mixture can easily burn. Remove from the heat and stir in the nuts.\nSpoon the filling into the unbaked tart shells so it’s level with the pastry. Bake for 15-18 minutes until set and pale golden. Leave in the tin to cool for a few minutes before lifting out on to a wire rack. Serve warm or cold.',NULL,'https://www.youtube.com/watch?v=WUpaOGghOdo','approved',0),
('Beef Lo Mein','STEP 1 - MARINATING THE BEEF In a bowl, add the beef, salt, 1 pinch white pepper, 1 Teaspoon sesame seed oil, 1/2 egg, corn starch,1 Tablespoon of oil and mix together.','https://www.themealdb.com/images/media/meals/1529444830.jpg','Chinese','General','Hard',15,50,4,'1/2 lb Beef\npinch Salt\npinch Pepper\n2 tsp Sesame Seed Oil\n1/2 Egg\n3 tbs Starch\n5 tbs Oil\n1/4 lb Noodles\n1/2 cup Onion\n1 tsp Minced Garlic\n1 tsp Ginger\n1 cup Bean Sprouts\n1 cup Mushrooms\n1 cup Water\n1 tbs Oyster Sauce\n1 tsp Sugar\n1 tsp Soy Sauce','STEP 1 - MARINATING THE BEEF\nIn a bowl, add the beef, salt, 1 pinch white pepper, 1 Teaspoon sesame seed oil, 1/2 egg, corn starch,1 Tablespoon of oil and mix together.\nSTEP 2 - BOILING THE THE NOODLES\nIn a 6 qt pot add your noodles to boiling water until the noodles are submerged and boil on high heat for 10 seconds. After your noodles is done boiling strain and cool with cold water.\nSTEP 3 - STIR FRY\nAdd 2 Tablespoons of oil, beef and cook on high heat untill beef is medium cooked.\nSet the cooked beef aside\nIn a wok add 2 Tablespoon of oil, onions, minced garlic, minced ginger, bean sprouts, mushrooms, peapods and 1.5 cups of water or until the vegetables are submerged in water.\nAdd the noodles to wok\nTo make the sauce, add oyster sauce, 1 pinch white pepper, 1 teaspoon sesame seed oil, sugar, and 1 Teaspoon of soy sauce.\nNext add the beef to wok and stir-fry',NULL,'https://www.youtube.com/watch?v=ZT9LSsNXXe0','approved',0),
('Croatian Bean Stew','Heat the oil in a pan. Add the chopped vegetables and sauté until tender.','https://www.themealdb.com/images/media/meals/tnwy8m1628770384.jpg','Croatian','General','Medium',5,60,4,'2 cans Cannellini Beans\n3 tbs Vegetable Oil\n2 cups Tomatoes\n5 Challots\n2 cloves Garlic\nPinch Parsley\n1/2 kg chopped Chorizo','Heat the oil in a pan. Add the chopped vegetables and sauté until tender. Take a pot, empty the beans together with the vegetables into it, put the sausages inside and cook for further 20 minutes on a low heat. Or, put it in an oven and bake it at a temperature of 180ºC/350ºF for 30 minutes. This dish is even better reheated the next day.',NULL,'https://www.youtube.com/watch?v=mrjnQal3S1A','approved',0),
('Ful Medames','As the cooking time varies depending on the quality and age of the beans, it is good to cook them in advance and to reheat them when you are ready to serve.','https://www.themealdb.com/images/media/meals/lvn2d51598732465.jpg','Egyptian','Vegetarian','Easy',20,10,4,'2 cups Broad Beans\n1/3 cup Parsley\nDash Olive Oil\n3 Lemons\n4 Garlic Clove\nSprinking Cumin','As the cooking time varies depending on the quality and age of the beans, it is good to cook them in advance and to reheat them when you are ready to serve. Cook the drained beans in a fresh portion of unsalted water in a large saucepan with the lid on until tender, adding water to keep them covered, and salt when the beans have softened. They take 2–2 1/2 hours of gentle simmering. When the beans are soft, let the liquid reduce. It is usual to take out a ladle or two of the beans and to mash them with some of the cooking liquid, then stir this back into the beans. This is to thicken the sauce.\nServe the beans in soup bowls sprinkled with chopped parsley and accompanied by Arab bread.\nPass round the dressing ingredients for everyone to help themselves: a bottle of extra-virgin olive oil, the quartered lemons, salt and pepper, a little saucer with the crushed garlic, one with chili-pepper flakes, and one with ground cumin.\nThe beans are eaten gently crushed with the fork, so that they absorb the dressing.\nOptional Garnishes\nPeel hard-boiled eggs—1 per person—to cut up in the bowl with the beans.\nTop the beans with a chopped cucumber-and-tomato salad and thinly sliced mild onions or scallions. Otherwise, pass round a good bunch of scallions and quartered tomatoes and cucumbers cut into sticks.\nServe with tahina cream sauce (page 65) or salad (page 67), with pickles and sliced onions soaked in vinegar for 30 minutes.\nAnother way of serving ful medames is smothered in a garlicky tomato sauce (see page 464).\nIn Syria and Lebanon, they eat ful medames with yogurt or feta cheese, olives, and small cucumbers.\nVariations\nA traditional way of thickening the sauce is to throw a handful of red lentils (1/4 cup) into the water at the start of the cooking.\nIn Iraq, large brown beans are used instead of the small Egyptian ones, in a dish called badkila, which is also sold for breakfast in the street.',NULL,'https://www.youtube.com/watch?v=ixpCabILuxw','approved',0),
('Beef Mechado','0. Make the beef tenderloin marinade by combining soy sauce, vinegar, ginger, garlic, sesame oil, olive oil, sugar, salt, and ground black pepper in a large bowl.','https://www.themealdb.com/images/media/meals/cgl60b1683206581.jpg','Filipino','General','Hard',25,20,4,'3 cloves Garlic\n1 sliced Onion\n2 Lbs Beef\n8 ounces Tomato Puree\n1 cup Water\n3 tbs Olive Oil\n1 Slice Lemon\n1 large Potatoes\n1/4 cup Soy Sauce\n1/2 tsp Black Pepper\n2 Bay Leaves\nTo taste Salt','0.\tMake the beef tenderloin marinade by combining soy sauce, vinegar, ginger, garlic, sesame oil, olive oil, sugar, salt, and ground black pepper in a large bowl. Mix well.\n1.\tAdd the cubed beef tenderloin to the bowl with the beef tenderloin marinade. Gently toss to coat the beef. Let it stay for 1 hour.\n2.\tUsing a metal or bamboo skewer, assemble the beef kebob by skewering the vegetables and marinated beef tenderloin.\n3.\tHeat-up the grill and start grilling the beef kebobs for 3 minutes per side. This will give you a medium beef that is juicy and tender on the inside. Add more time if you want your beef well done, but it will be less tender.\n4.\tTransfer to a serving plate. Serve with Saffron rice.\n5.\tShare and enjoy!',NULL,'https://www.youtube.com/watch?v=jxW3Lj8VjyE','approved',0),
('Gigantes Plaki','Soak the beans overnight in plenty of water.','https://www.themealdb.com/images/media/meals/b79r6f1585566277.jpg','Greek','Vegetarian','Medium',15,20,4,'400g Butter Beans\n3 tbs Olive Oil\n1 chopped Onion\n2 chopped Garlic Clove\n2 tbs Tomato Puree\n800g Tomatoes\n1 tbs Sugar\n1 tbs Dried Oregano\nPinch Cinnamon\n2 tbs Chopped Parsley','Soak the beans overnight in plenty of water. Drain, rinse, then place in a pan covered with water. Bring to the boil, reduce the heat, then simmer for approx 50 mins until slightly tender but not soft. Drain, then set aside.\n\nHeat oven to 180C/160C fan/gas 4. Heat the olive oil in a large frying pan, tip in the onion and garlic, then cook over a medium heat for 10 mins until softened but not browned. Add the tomato purée, cook for a further min, add remaining ingredients, then simmer for 2-3 mins. Season generously, then stir in the beans. Tip into a large ovenproof dish, then bake for approximately 1 hr, uncovered and without stirring, until the beans are tender. The beans will absorb all the fabulous flavours and the sauce will thicken. Allow to cool, then scatter with parsley and drizzle with a little more olive oil to serve.',NULL,'https://www.youtube.com/watch?v=e-2K2iyPASA','approved',0),
('Chilli prawn linguine','Mix the dressing ingredients in a small bowl and season with salt and pepper.','https://www.themealdb.com/images/media/meals/usywpp1511189717.jpg','Italian','General','Hard',20,40,4,'280g Linguine Pasta\n200g Sugar Snap Peas\n2 tblsp Olive Oil\n2 cloves chopped Garlic Clove\n1 large Red Chilli\n24 Skinned King Prawns\n12 Cherry Tomatoes\nHandful Basil Leaves\nLeaves Lettuce\nto serve Bread\n2 tbsp Fromage Frais\nGrated Zest of 2 Lime\n2 tsp Caster Sugar','Mix the dressing ingredients in a small bowl and season with salt and pepper. Set aside.\n\nCook the pasta according to the packet instructions. Add the sugar snap peas for the last minute or so of cooking time.\n\nMeanwhile, heat the oil in a wok or large frying pan, toss in the garlic and chilli and cook over a fairly gentle heat for about 30 seconds without letting the garlic brown. Tip in the prawns and cook over a high heat, stirring frequently, for about 3 minutes until they turn pink.\n\nAdd the tomatoes and cook, stirring occasionally, for 3 minutes until they just start to soften. Drain the pasta and sugar snaps well, then toss into the prawn mixture. Tear in the basil leaves, stir, and season with salt and pepper.\n\nServe with salad leaves drizzled with the lime dressing, and warm crusty bread.',NULL,'https://www.youtube.com/watch?v=SC17Mc70Db0','approved',0),
('Callaloo Jamaican Style','Cut leaves and soft stems from the kale branches, them soak in a bowl of cold water for about 5-10 minutes or until finish with prep.','https://www.themealdb.com/images/media/meals/ussyxw1515364536.jpg','Jamaican','General','Medium',10,60,4,'1  bunch Kale\n2 strips Bacon\n3 cloves Chopped Garlic\n1 medium Onion\n1/2 tsp Paprika\n1 Sprig Thyme\n1 Tomato\n1 Red Pepper\n4 Banana\nSplash Vegetable Oil','Cut leaves and soft stems from the kale branches, them soak in a bowl of cold water for about 5-10 minutes or until finish with prep.\nProceed to slicing the onions, mincing the garlic and dicing the tomatoes. Set aside\nRemove kale from water cut in chunks.\nPlace bacon on saucepan and cook until crispy. Then add onions, garlic, thyme, stir for about a minute or more\nAdd tomatoes; scotch bonnet pepper, smoked paprika. Sauté for about 2-3 more minutes.\nFinally add vegetable, salt, mix well, and steamed for about 6-8 minutes or until leaves are tender. Add a tiny bit of water as needed. Adjust seasonings and turn off the heat.\nUsing a sharp knife cut both ends off the plantain. This will make it easy to grab the skin of the plantains. Slit a shallow line down the long seam of the plantain; peel only as deep as the peel. Remove plantain peel by pulling it back.\nSlice the plantain into medium size lengthwise slices and set aside.\nCoat a large frying pan with cooking oil spray. Spray the tops of the plantains with a generous layer of oil spray and sprinkle with salt, freshly ground pepper.\nLet the plantains "fry" on medium heat, shaking the frying pan to redistribute them every few minutes.\nAs the plantains brown, continue to add more cooking oil spray, salt and pepper (if needed) until they have reached the desired color and texture.\nRemove and serve with kale',NULL,'https://www.youtube.com/watch?v=bCr3GasJWwE','approved',0),
('Japanese gohan rice','STEP 1 Rinsing and soaking your rice is key to achieving the perfect texture.','https://www.themealdb.com/images/media/meals/kw92t41604181871.jpg','Japanese','General','Easy',30,20,6,'300g Sushi Rice\n1 tbs Mirin\nGarnish Pickle Juice\nGarnish Spring Onions','STEP 1\nRinsing and soaking your rice is key to achieving the perfect texture. Measure the rice into a bowl, cover with cold water, then use your fingers to massage the grains of rice – the water will become cloudy. Drain and rinse again with fresh water. Repeat five more times until the water stays clear.\n\nSTEP 2\nTip the rinsed rice into a saucepan with 400ml water, or 200ml dashi and 200ml water, bring to the boil, then turn down the heat to a low simmer, cover with a tight-fitting lid with a steam hole and cook for 15 mins. Remove from the heat and leave to sit for another 15 mins, then stir through the mirin. Remove the lid and give it a good stir. Serve with any or all of the optional toppings.',NULL,'https://www.youtube.com/watch?v=rZO86_-MIp0','approved',0),
('Beef Rendang','Chop the spice paste ingredients and then blend it in a food processor until fine.','https://www.themealdb.com/images/media/meals/bc8v651619789840.jpg','Malaysian','General','Hard',10,10,4,'1lb Beef\n5 tbs Vegetable Oil\n1 Cinnamon Stick\n3 Cloves\n3 Star Anise\n3 Cardamom\n1 cup Coconut Cream\n1 cup Water\n2 tbs Tamarind Paste\n6 Lime\n1 tbs Sugar\n5 Challots','Chop the spice paste ingredients and then blend it in a food processor until fine.\nHeat the oil in a stew pot, add the spice paste, cinnamon, cloves, star anise, and cardamom and stir-fry until aromatic. Add the beef and the pounded lemongrass and stir for 1 minute. Add the coconut milk, tamarind juice, water, and simmer on medium heat, stirring frequently until the meat is almost cooked. Add the kaffir lime leaves, kerisik (toasted coconut), sugar or palm sugar, stirring to blend well with the meat.\nLower the heat to low, cover the lid, and simmer for 1 to 1 1/2 hours or until the meat is really tender and the gravy has dried up. Add more salt and sugar to taste. Serve immediately with steamed rice and save some for overnight.',NULL,'https://www.youtube.com/watch?v=Ot-dmfBaZrA','approved',0),
('Lamb tomato and sweet spices','Use pickled vine leaves here, preserved in brine.','https://www.themealdb.com/images/media/meals/qtwtss1468572261.jpg','Moroccan','General','Hard',5,30,4,'2 tbsp olive oil\n4cm piece finely chopped ginger\n2 cloves peeled and chopped garlic\n800g peeled and chopped tomatoes\n2 tbsp lemon juice\n1 tsp caster sugar\n50 vine leaves\n1 large fennel bulb\n400g lamb mince\n1 medium onion\n1 small peeled and coarsely grated potatoes\n2 tbsp basmati rice\n2 tbsp chopped parsley\n2 tbsp chopped coriander\n1 tbsp lemon juice\n2 cloves garlic\n½ tsp ground clove\n½ tsp ground cinnamon\n2 medium tomatoes','Use pickled vine leaves here, preserved in brine. Small delicate leaves are better than the large bristly ones but, if only large leaves are to hand, then trim them to roughly 12 by 12 cms so that you don\'t get too many layers of leaves around the filling. And remove any stalks. Drain the preserved leaves, immerse them in boiling water for 10 minutes and then leave to dry on a tea towel before use. \nBasmati rice with butter and pine nuts is an ideal accompaniment. Couscous is great, too. Serves four.\nFirst make the filling. Put all the ingredients, apart from the tomatoes, in a bowl. Cut the tomatoes in half, coarsely grate into the bowl and discard the skins. Add half a teaspoon of salt and some black pepper, and stir. Leave on the side, or in the fridge, for up to a day. Before using, gently squeeze with your hands and drain away any juices that come out.\nTo make the sauce, heat the oil in a medium pan. Add the ginger and garlic, cook for a minute or two, taking care not to burn them, then add the tomato, lemon juice and sugar. Season, and simmer for 20 minutes.\nWhile the sauce is bubbling away, prepare the vine leaves. Use any torn or broken leaves to line the base of a wide, heavy saucepan. Trim any leaves from the fennel, cut it vertically into 0.5cm-thick slices and spread over the base of the pan to cover completely.\nLay a prepared vine leaf (see intro) on a work surface, veiny side up. Put two teaspoons of filling at the base of the leaf in a 2cm-long by 1cm-wide strip. Fold the sides of the leaf over the filling, then roll it tightly from bottom to top, in a cigar shape. Place in the pan, seam down, and repeat with the remaining leaves, placing them tightly next to each other in lines or circles (in two layers if necessary).\nPour the sauce over the leaves (and, if needed, add water just to cover). Place a plate on top, to weigh the leaves down, then cover with a lid. Bring to a boil, reduce the heat and cook on a bare simmer for 70 minutes. Most of the liquid should evaporate. Remove from the heat, and leave to cool a little - they are best served warm. When serving, bring to the table in the pan - it looks great. Serve a few vine leaves and fennel slices with warm rice. Spoon the braising juices on top and garnish with coriander.',NULL,'https://www.youtube.com/watch?v=vaZb1MnFBgA','approved',0),
('Bigos (Polish hunter\'s stew)','step 1 Put the cabbage in a heavy casserole dish, add the stock and cook over a low heat for about 50 mins, until tender.','https://www.themealdb.com/images/media/meals/fl4brj1764361323.jpg','Polish','General','Hard',15,30,4,'1 sliced White Cabbage\n250ml Beef Stock\n100g Mushrooms\n2 tablespoons Lard\n400g German Sausages\n250g Bacon\n2 chopped Onion\n750g Beef\n200g Prunes\n1 Bay Leaf\n2 Cloves\n12 Peppercorns\n4 Juniper Berries\n4 Allspice Berries\n90 ml Red Wine\n2 tablespoons Tomato Puree','step 1\nPut the cabbage in a heavy casserole dish, add the stock and cook over a low heat for about 50 mins, until tender.\n\nstep 2\nCut the soaked mushrooms into strips and save the soaking water. Heat the lard and fry the sausages and bacon, then scoop out, leaving the fat in the pan. Fry the onion in the same pan for 5-8 mins until lightly browned.\n\nstep 3\nAdd the mushrooms and their liquid along with all the cooked meat, onions and prunes, then cover and cook for 20 mins. Add the spices, red wine and tomato purée and bring to a simmer, then cover and cook for 1 hr. Season well and leave to cool. Will keep covered and chilled for up to two days. Bigos improves in flavour over a couple of days. Leave to cool first. Reheat until piping hot before serving.',NULL,'https://www.youtube.com/watch?v=Oqg_cO4s8ik','approved',0),
('Piri-piri chicken and slaw','STEP 1 Whizz together all of the marinade ingredients in a small food processor.','https://www.themealdb.com/images/media/meals/hglsbl1614346998.jpg','Portuguese','General','Hard',30,10,4,'1.5kg Chicken\n3 chopped Red Chilli\n2 cloves Garlic\n1 tsp Ginger\n1 tsp Dried Oregano\n1 tsp Coriander\n1 tsp Paprika\n2 tbs Red Wine Vinegar\n2 tbs Oil\n1 sliced Red Onions\n2 Carrots\n1 Beetroot\n4 leaves Cabbage\n2 tbs Mayonnaise\n2 tbs Greek Yogurt\n2 tbs Red Wine Vinegar\n1 tsp Cumin Seeds','STEP 1\n\nWhizz together all of the marinade ingredients in a small food processor. Rub the marinade onto the chicken and leave for 1 hour at room temperature.\n\nSTEP 2\n\nHeat the oven to 190C/fan 170C/gas 5. Put the chicken in a roasting tray and cook for 1 hour 20 minutes. Rest under loose foil for 20 minutes. While the chicken is resting, mix together the slaw ingredients and season. Serve the chicken with slaw, fries and condiments.',NULL,'https://www.youtube.com/watch?v=_RKwKjskopk','approved',0),
('Cabbage Soup (Shchi)','Add the butter to a large Dutch oven or other heavy-duty pot over medium heat.','https://www.themealdb.com/images/media/meals/60oc3k1699009846.jpg','Russian','Vegetarian','Hard',10,40,4,'3 tbs Unsalted Butter\n1 large Onion\n1 medium Cabbage\n1 Carrots\n1 Celery\n1 Bay Leaf\n8 cups Vegetable Stock\n2 large Potatoes\n2 large Tomatoes\nGarnish Sour Cream\nGarnish Dill','Add the butter to a large Dutch oven or other heavy-duty pot over medium heat. When the butter has melted, add the onion and sauté until translucent.\nAdd the cabbage, carrot, and celery. Sauté until the vegetables begin to soften, stirring frequently, about 3 minutes.\nAdd the bay leaf and vegetable stock and bring to a boil over high heat. Reduce the heat to low and simmer, covered, until the vegetables are crisp-tender, about 15 minutes.\nAdd the potatoes and bring it back to a boil over high heat. Reduce the heat to low and simmer, covered, until the potatoes are tender, about 10 minutes.\nAdd the tomatoes (or undrained canned tomatoes) and bring the soup back to a boil over high heat. Reduce the heat to low and simmer, uncovered, for 5 minutes. Season to taste with salt and pepper.\nemove and discard the bay leaf from the pot.\nServe topped with fresh sour cream and fresh dill.',NULL,'https://www.youtube.com/watch?v=lTjlbqGc_Y8','approved',0),
('Knafeh','1 Take kanfhe in a bowl and roughly cut them.','https://www.themealdb.com/images/media/meals/76nffj1763593933.jpg','Saudi Arabian','General','Hard',15,30,8,'400g Knafeh\n6 tablespoons Unsalted Butter\n1 pinch Yellow Food Colouring\n1 cup Mozzarella\n1/4 cup Cream Cheese\n1 1/2 cup Milk\n4 tablespoons Sugar\n2 tablespoons Corn Flour\n1 cup Sugar\n1 cup Water\n1 tsp Rose water\n1/2 teaspoon Lemon Juice','1\nTake kanfhe in a bowl and roughly cut them. Pour melted butter, yellow food color and mix well with your hands.\nIn a separate bowl mix milk, cream cheese, sugar, cornstarch well.\n2\nTurn on the flame and boil the liquid, when it gets thick turn off the flame let it cool down a little bit.\nAdd mozzarella in it and mix it well.\nNow make a base with half of the kanfhe in a dish, gently press it to level the dough well.\nPour the cheese mixture on the top and level it with a spoon.\n3\nCover it with the other half of the kanfhe.\nPut the dish in a preheated oven at 200 degree for about 20-25 minutes.\nIt\'s ready when kunafa is golden and crunchy in the surface.\n4\nBoil water in a pan and dissolve sugar in it for 4–5 minutes. OR cook it until slightly thicken and keep on stirring. Add lemon juice with rose water, mix well.\nEvenly pour the syrup over the kunafa as soon as it comes out of the oven.\nYour kunafa is ready to serve.',NULL,'https://www.youtube.com/watch?v=3EF_R7__xu4','approved',0),
('Arroz al horno (baked rice)','step 1 Heat oven to 200C/180C/gas 6.','https://www.themealdb.com/images/media/meals/qt4i0n1763256454.jpg','Spanish','General','Hard',15,60,4,'2 tbsp Extra Virgin Olive Oil\n800g Pork belly slices\n150g Black Pudding\n100g Bacon lardon\n1 chopped Onion\n2 Red Pepper\n1 chopped Plum Tomatoes\n8 Garlic Clove\n4 teaspoons Paprika\n1/2 teaspoon Chilli Flakes\n200g Dried white beans\n1 1/2 L Chicken Stock\n6 parts Thyme\n375g Paella Rice\n1 Lemon Juice','step 1\nHeat oven to 200C/180C/gas 6. Heat half the oil in a deep frying or sauté pan (or shallow casserole dish) measuring around 30cm in diameter. Over a high heat, colour the pork belly slices on each side in several batches, then transfer to a bowl. Add the remaining oil to the pan and lower the heat to medium, then add the black pudding and bacon and fry all over for several mins. Remove with a slotted spoon. Fry the onion and peppers for around 10 mins until soft and pale gold, then add the tomato and cook until soft. Add the garlic, smoked paprika and chilli flakes and cook for another 2 mins, then put the pork, black pudding and bacon back in the pan. Add the beans, stock and whichever herb you\'re using, and bring everything to the boil.\n\nstep 2\nSprinkle the rice around the pork belly, pushing it underneath the stock. Let the stock come to the boil again, season well, then transfer to the oven (leave it uncovered). Cook for 20 mins without stirring, then check to see how the rice is doing. The rice should be tender and the stock absorbed. If it’s not ready, put back in the oven for another 5 mins, then check again. Taste for seasoning.\n\nstep 3\nSqueeze lemon juice over the top and drizzle over some extra virgin olive oil just before serving, if you like.',NULL,'https://www.youtube.com/watch?v=f-waAIrn2iA','approved',0),
('Fasoliyyeh Bi Z-Zayt (Syrian Green Beans with Olive Oil)','Place the green beans into a large pot, and drizzle with olive oil.','https://www.themealdb.com/images/media/meals/21yc5s1760524759.jpg','Syrian','Vegan','Easy',25,50,4,'16 ounces Green Beans\n1/4 cup Olive Oil\nDash Salt\n1 clove Garlic\n1/4 cup Cilantro','Place the green beans into a large pot, and drizzle with olive oil. Season with salt to taste, and put the lid on the pot. Cook over medium-high heat, stirring occasionally, until beans are cooked to your desired doneness. Syrians like it cooked until the green beans are turning brownish in color. The idea is not to saute them, but to let them steam in the moisture released by the ice crystals.\n\nAdd cilantro and garlic to the beans, and continue to cook just until the cilantro has started to wilt. Eat as a main course by scooping up with warm pita bread or serve as a side dish.',NULL,'https://www.youtube.com/watch?v=_EadiEPxQI0','approved',0),
('Massaman Beef curry','Heat oven to 200C/180C fan/gas 6, then roast the peanuts on a baking tray for 5 mins until golden brown.','https://www.themealdb.com/images/media/meals/tvttqv1504640475.jpg','Thai','General','Hard',20,60,4,'85g Peanuts\n400ml can Coconut cream\n4 tbsp Massaman curry paste\n600g stewing cut into strips Beef\n450g waxy Potatoes\n1 cut thin wedges Onion\n4 leaves Lime\n1 Cinnamon stick\n1 tbsp Tamarind paste\n1 tbsp palm or soft light Brown sugar\n1 tbsp Fish Sauce\n1 red deseeded and finely sliced, to serve chilli\nto serve Jasmine Rice','Heat oven to 200C/180C fan/gas 6, then roast the peanuts on a baking tray for 5 mins until golden brown. When cool enough to handle, roughly chop. Reduce oven to 180C/160C fan/gas 4.\nHeat 2 tbsp coconut cream in a large casserole dish with a lid. Add the curry paste and fry for 1 min, then stir in the beef and fry until well coated and sealed. Stir in the rest of the coconut with half a can of water, the potatoes, onion, lime leaves, cinnamon, tamarind, sugar, fish sauce and most of the peanuts. Bring to a simmer, then cover and cook for 2 hrs in the oven until the beef is tender.\nSprinkle with sliced chilli and the remaining peanuts, then serve straight from the dish with jasmine rice.',NULL,'https://www.youtube.com/watch?v=mVxgZSCU9_g','approved',0),
('Kafteji','Peel potatoes and cut into 5cm cubes.','https://www.themealdb.com/images/media/meals/1bsv1q1560459826.jpg','Tunisian','Vegetarian','Medium',20,30,4,'5 Large Potatoes\n2 tbs Olive Oil\n1 Green Pepper\n5 Onions\n1 tbs Ras el hanout\n500g Pumpkin\n24 Skinned Eggs\nPinch Salt\nPinch Pepper','Peel potatoes and cut into 5cm cubes.\nPour 1-2 cm of olive oil into a large pan and heat up very hot. Fry potatoes until golden brown for 20 minutes, turning from time to time. Place on kitchen paper to drain.\nCut the peppers in half and remove seeds. Rub a little olive oil on them and place the cut side down on a baking tray. Place them under the grill. Grill until the skin is dark and bubbly. While the peppers are still hot, put them into a plastic sandwich bag and seal it. Take them out after 15 minutes and remove skins.\nIn the meantime, heat more olive oil another pan. Peel the onions and cut into thin rings. Fry for 15 minutes until golden brown, turning them often. Add the Ras el hanout at the end.\nCut the pumpkin into 5cm cubes and fry in the same pan you used for the potatoes for 10-15 minutes until it is soft and slightly browned. Place on kitchen paper.\nPour the remaining olive oil out of the pan and put all the cooked vegetables into the pan and mix. Whisk eggs and pour them over the vegetables. Put the lid on the pan so that the eggs cook. Put the contents of the pan onto a large chopping board, add salt and pepper and chopped and mix everything with a big knife.',NULL,'https://www.youtube.com/watch?v=-TFf-Zu-xQU','approved',0),
('Aubergine & hummus grills','step 1 Lay the aubergine out in one layer on a large baking sheet.','https://www.themealdb.com/images/media/meals/zub3s91764110535.jpg','Turkish','Vegetarian','Medium',25,20,4,'2 Aubergine\n2 tablespoons Vegetable Oil\n3 sliced thinly Bread\n300g Hummus\n100g Walnuts\n40g Parsley\n200g Cherry Tomatoes\nJuice of 1/2 Lemon\nSplash Extra Virgin Olive Oil','step 1\nLay the aubergine out in one layer on a large baking sheet. Brush sparingly with vegetable oil, then season generously. Grill for 15 mins, turning twice and brushing with oil until the slices are softened and cooked through. Meanwhile, whizz the bread into crumbs. Add 2 tsp oil and whizz briefly again, to coat.\n\nstep 2\nSpread a couple of tsps of hummus on top of each slice of aubergine. Tip the breadcrumbs onto a large plate, then press the hummus side of the aubergines into the crumbs to coat. Grill again, crumb-side up, for about 3 mins until golden.\n\nstep 3\nToss the walnuts, parsley and cherry tomatoes in a bowl, season, then add the lemon juice and olive oil and toss again. Serve the grills with the salad, a dollop more hummus and some pitta bread.',NULL,'https://www.youtube.com/watch?v=P5LD03XptB8','approved',0),
('Beetroot Soup (Borscht)','Chop the beetroot, add water and stock cube and cook for 15mins.','https://www.themealdb.com/images/media/meals/zadvgb1699012544.jpg','Ukrainian','Vegetarian','Medium',15,50,4,'3 Beetroot\n4 tbs Olive Oil\n1 Chicken Stock Cube\n6 cups Water\n3 Potatoes\n1 can Cannellini Beans\nGarnish Dill','Chop the beetroot, add water and stock cube and cook for 15mins. Add the other ingredients and boil until soft. Finally add the beans and cook for 5mins. Serve in the soup pot.',NULL,'https://www.youtube.com/watch?v=6CXgPVw_-0g','approved',0),
('Chivito uruguayo','Crush the meat so that it is finite and we put it on a griddle to brown.','https://www.themealdb.com/images/media/meals/n7qnkb1630444129.jpg','Uruguayan','General','Medium',30,40,4,'2 Beef Brisket\n2 Bread\n1 Lettuce\n1 Tomato\n100g Ham\n100g Mozzarella\n100g Bacon\n1 Egg\n1 Onion\n1 Pepper','Crush the meat so that it is finite and we put it on a griddle to brown. Put the eggs, bacon and ham to fry.\nCut the bread in half, put the beef brisket, the fried eggs, the bacon, the ham, the mozzarella, the tomato and the lettuce. Cover with the other half of the bread and serve.',NULL,'https://www.youtube.com/watch?v=0PXbbL1QdaA','approved',0),
('Algerian Kefta (Meatballs)','Combine ground beef with 1/2 of the minced garlic and 1 tablespoon chopped onion in a large bowl.','https://www.themealdb.com/images/media/meals/8rfd4q1764112993.jpg','Algerian','General','Medium',10,50,4,'1 lb Ground Beef\n4 Cloves Crushed Garlic\n1/2 cup Onion\nTo taste Salt\nTo taste Pepper\n3 Plum Tomatoes\n1 tsp Parsley\n1/2 cup Water','Combine ground beef with 1/2 of the minced garlic and 1 tablespoon chopped onion in a large bowl. Mix with your hands until fully incorporated. Shape meat mixture into 1 1/2-inch oblong patties; you should have 12 to 14 meatballs.\n\nHeat a large skillet over medium-high heat. Brown patties in batches in the hot skillet until crispy on both sides and no longer pink in the center, about 10 minutes. Set meatballs aside in a rimmed serving dish.\n\nReduce heat to medium and stir remaining chopped onion into drippings in the skillet. Season with salt and pepper. Cook, stirring constantly, until onion has softened and turned translucent, about 5 minutes. Stir in remaining garlic and cook for 30 seconds. Stir in Roma tomatoes, dried parsley, and ras el hanout. Pour in water. Cook until tomatoes are soft, about 5 minutes.\n\nPour tomato sauce over meatballs to serve.',NULL,'https://www.youtube.com/watch?v=IRadJQNLvPs','approved',0),
('Baked salmon with fennel & tomatoes','Heat oven to 180C/fan 160C/gas 4.','https://www.themealdb.com/images/media/meals/1548772327.jpg','British','General','Medium',20,50,4,'2 medium Fennel\n2 tbs chopped Parsley\nJuice of 1 Lemon\n175g Cherry Tomatoes\n1 tbs Olive Oil\n350g Salmon\nto serve Black Olives','Heat oven to 180C/fan 160C/gas 4. Trim the fronds from the fennel and set aside. Cut the fennel bulbs in half, then cut each half into 3 wedges. Cook in boiling salted water for 10 mins, then drain well. Chop the fennel fronds roughly, then mix with the parsley and lemon zest.\n\nSpread the drained fennel over a shallow ovenproof dish, then add the tomatoes. Drizzle with olive oil, then bake for 10 mins. Nestle the salmon among the veg, sprinkle with lemon juice, then bake 15 mins more until the fish is just cooked. Scatter over the parsley and serve.',NULL,'https://www.youtube.com/watch?v=xvPR2Tfw5k0','approved',0),
('Classic Tourtière','Heat oil on medium-high heat in a large sauté pan or skillet, then sauté the onion and garlic until softened, about 5 minutes.','https://www.themealdb.com/images/media/meals/0sd7ac1764787957.jpg','Canadian','General','Hard',20,40,4,'2 tablespoons Canola Oil\n1 chopped Onion\n2 cloves minced Garlic\n1 lb Ground Beef\n1 lb Ground Pork\n1 tsp Dried Leaves Of Summer Savoury\nTo taste Salt\nTo taste Pepper\n1/2 tsp Ground Clove\n1/2 tsp Ground Nutmeg\n1 Bay Leaf\n1 cup Beef Stock\n1 small Russet Potato\n4 Shortcrust Pastry\n1 beaten Egg','Heat oil on medium-high heat in a large sauté pan or skillet, then sauté the onion and garlic until softened, about 5 minutes. Add the ground beef, pork, and spices and cook until the meat is browned.\nAdd the beef broth and bring it up to a simmer then reduce heat to medium low. Add the grated potato and stir it in. Cook until liquid is almost absorbed, about 15 min. Remove the bay leaves and add salt to taste. Remove the pan from the heat and let the mixture cool completely — it bakes best if the filling is chilled.\nPreheat the oven to 375 °F (190 °C). On a lightly floured surface, roll out one disc of the pie dough to less than the 1/4-inch thickness and line the 9-inch pie plate. Fill this with the cooled tourtière mixture and spread out evenly. Roll out the remaining dough to the same thickness, cut a hole in the centre (for steam to escape) and place on top of the filling. Trim the dough to 1/2-inch beyond the edge of the pie plate and pinch the edges of the crust together. Brush the crust with the egg wash.\nBake tourtière for about 45 minutes or until the pastry is a rich golden brown. Let cool for 15 minutes before slicing to serve.\nServes: 8-10 (makes 2 9-inch pies)',NULL,'https://www.youtube.com/watch?v=PM9TZPUJTiU','approved',0),
('Chicken Congee','STEP 1 - MARINATING THE CHICKEN In a bowl, add chicken, salt, white pepper, ginger juice and then mix it together well.','https://www.themealdb.com/images/media/meals/1529446352.jpg','Chinese','General','Medium',5,20,4,'8 oz Chicken\npinch Salt\npinch Pepper\n1 tsp Ginger Cordial\n1 tsp Ginger\n1 tbs Spring Onions\n1/2 cup Rice\n8 cups Water\n2 oz Coriander','STEP 1 - MARINATING THE CHICKEN\nIn a bowl, add chicken, salt, white pepper, ginger juice and then mix it together well.\nSet the chicken aside.\nSTEP 2 - RINSE THE WHITE RICE\nRinse the rice in a metal bowl or pot a couple times and then drain the water.\nSTEP 2 - BOILING THE WHITE RICE\nNext add 8 cups of water and then set the stove on high heat until it is boiling. Once rice porridge starts to boil, set the stove on low heat and then stir it once every 8-10 minutes for around 20-25 minutes.\nAfter 25 minutes, this is optional but you can add a little bit more water to make rice porridge to make it less thick or to your preference.\nNext add the marinated chicken to the rice porridge and leave the stove on low heat for another 10 minutes.\nAfter an additional 10 minutes add the green onions, sliced ginger, 1 pinch of salt, 1 pinch of white pepper and stir for 10 seconds.\nServe the rice porridge in a bowl\nOptional: add Coriander on top of the rice porridge.',NULL,'https://www.youtube.com/watch?v=kqEfk801E94','approved',0),
('Croatian lamb peka','Preheat oven to 200°C fan / 220°C / 425°F / Gas mark 7 If you have not bought diced lamb, cut your lamb shoulder or leg into large chunks and place to one side.','https://www.themealdb.com/images/media/meals/pn59o51628769837.jpg','Croatian','General','Hard',25,40,4,'600g Potatoes\n1 chopped Courgettes\n1 chopped Carrots\n1 chopped Green Pepper\n1 small Aubergine\n1 Large Chopped Onion\n800g Lamb Shoulder\n1 tbs Garlic Sauce\n1 tbs Tomato Puree\n80 ml Olive Oil\nSprinking Thyme\n250ml White Wine\nPinch Pepper','Preheat oven to 200°C fan / 220°C / 425°F / Gas mark 7\nIf you have not bought diced lamb, cut your lamb shoulder or leg into large chunks and place to one side.\nChunks of chopped lamb of a red chopping board\nMake oil marinade -\nMix 80ml of olive oil in a bowl with garlic puree, sundried tomato puree ,black pepper and salt.\nolive oil, gia sundried tomato puree and gia garlic puree and black pepper mixed together in a silver bowl to make Croatian peka\nAdd potatoes and vegetables into a large lidded casserole dish.\nChopped up vegetables which consist of chopped up red onion, courgette, potatoes red peppers in a cast iron pan\nPlace diced lamb on top of the vegetables, pour the marinade and wine over the top.\nChunks of lamb covered in in a sundried tomato oil sauce which is on top of chopped red onion, aubergine, courgette and potatoes in a cast iron pan\nAdd the rosemary, thyme and sage, trying to keep the herbs on top.\nSo you can easily remove the herb stalks once cooked.\nChunks of lamb coated in a sundried tomato oil sauce and covered with thyme, rosemary and sage which is on top of chopped red onion, aubergine, courgette and potatoes in a cast iron pan\nPlace lid on the casserole dish and cook for 1hr 30 minute\nIf you do not have a lid cover very well with kitchen foil\nCast iron dish with lid on in the oven\nTake the lid off, remove any thick herb stems. Stir in 2 tbsp of olive oil.\nCook for a further 20-30 mins.\nCooked Croatian Lamb Peka in a cast iron pan in the oven\nServe with fresh homemade bread to dip into the juices.',NULL,'https://www.youtube.com/watch?v=K0ipnz4fwJI','approved',0),
('Koshari','Cook the lentils. Bring lentils and 4 cups of water to a boil in a medium pot or saucepan over high heat.','https://www.themealdb.com/images/media/meals/4er7mj1598733193.jpg','Egyptian','Vegetarian','Medium',30,30,4,'1 1/2 cups Brown Lentils\n1 1/2 cups Rice\n1/2 tsp Coriander\n2 cups Macaroni\nCan Chickpeas\n1 large Onion\nSprinking Salt\n1/2 cup Vegetable Oil','Cook the lentils. Bring lentils and 4 cups of water to a boil in a medium pot or saucepan over high heat. Reduce the heat to low and cook until lentils are just tender (15-17 minutes). Drain from water and season with a little salt. (Note: when the lentils are ready, they should not be fully cooked. They should be only par-cooked and still have a bite to them as they need to finish cooking with the rice).\nNow, for the rice. Drain the rice from its soaking water. Combine the par-cooked lentils and the rice in the saucepan over medium-high heat with 1 tbsp cooking oil, salt, pepper, and coriander. Cook for 3 minutes, stirring regularly. Add warm water to cover the rice and lentil mixture by about 1 1/2 inches (you’ll probably use about 3 cups of water here). Bring to a boil; the water should reduce a bit. Now cover and cook until all the liquid has been absorbed and both the rice and lentils are well cooked through (about 20 minutes).  Keep covered and undisturbed for 5 minutes or so.\nNow make the pasta. While the rice and lentils are cooking, make the pasta according to package instructions by adding the elbow pasta to boiling water with a dash of salt and a little oil. Cook until the pasta is al dente. Drain.\nCover the chickpeas and warm in the microwave briefly before serving.\n\nMake the crispy onion topping. \n\nSprinkle the onion rings with salt, then toss them in the flour to coat. Shake off excess flour.\nIn a large skillet, heat the cooking oil over medium-high heat, cook the onion rings, stirring often, until they turn a nice caramelized brown. Onions must be crispy, but not burned (15-20 minutes).',NULL,'https://www.youtube.com/watch?v=y0d2ZMZBW4Y','approved',0),
('Bistek','0. Marinate beef in soy sauce, lemon (or calamansi), and ground black pepper for at least 1 hour.','https://www.themealdb.com/images/media/meals/4pqimk1683207418.jpg','Filipino','General','Medium',30,30,4,'1 lb Beef\n5 tablespoons Soy Sauce\n1 Lemon\n3 cloves Garlic\n3 parts Onion\n4 tbs Olive Oil\n1 cup Water\n1 pinch Salt','0.\tMarinate beef in soy sauce, lemon (or calamansi), and ground black pepper for at least 1 hour. Note: marinate overnight for best result\n1.\tHeat the cooking oil in a pan then pan-fry half of the onions until the texture becomes soft. Set aside\n2.\tDrain the marinade from the beef. Set it aside. Pan-fry the beef on the same pan where the onions were fried for 1 minute per side. Remove from the pan. Set aside\n3.\tAdd more oil if needed. Saute garlic and remaining raw onions until onion softens.\n4.\tPour the remaining marinade and water. Bring to a boil.\n5.\tAdd beef. Cover the pan and simmer until the meat is tender. Note: Add water as needed.\n6.\tSeason with ground black pepper and salt as needed. Top with pan-fried onions.\n7.\tTransfer to a serving plate. Serve hot. Share and Enjoy!',NULL,'https://www.youtube.com/watch?v=xOQON5_S7as','approved',0),
('Honey Yogurt Cheesecake','Heat oven to 160C/140C fan/gas 3.','https://www.themealdb.com/images/media/meals/y2irzl1585563479.jpg','Greek','General','Medium',20,40,8,'100g Digestive Biscuits\n85g Almonds\n85g Butter\n250ml Greek Yogurt\n750g Mascarpone\n2 Eggs\nZest of 1 Lemon\nZest of 1 Orange\n250ml Honey\nTo serve Fruit Mix','Heat oven to 160C/140C fan/gas 3. Crush the biscuits and most of the almonds inside a plastic food bag using a rolling pin. Mix with the butter, then press into the bottom of a deep, oval, 23cm dish (or something similar in size – a roasting tin, baking dish or cake tin will work). Bake for 10 mins until crisp.\n\nStir or mash together the yogurt and mascarpone, then whisk in the eggs, one at a time. Stir in the lemon and orange zests, then stir in most of the honey, reserving about 3 tbsp. Spread over the biscuit base, cover loosely with foil and cook for 1 hr. Remove the foil and cook for 15 mins more until lightly golden and the top is firm with just the slightest wobble in the middle. Leave to cool. Can be kept in the fridge for up to 2 days.\n\nTo serve, scatter with almonds, drizzle over the remaining honey, and hand around fresh fruit to go with it.',NULL,'https://www.youtube.com/watch?v=JE8crtueXs8','approved',0),
('Fettuccine Alfredo','Cook pasta according to package instructions in a large pot of boiling water and salt.','https://www.themealdb.com/images/media/meals/0jv5gx1661040802.jpg','Italian','General','Easy',5,50,4,'1 lb Fettuccine\n1/2 cup Heavy Cream\n1/2 cup Butter\n1/2 cup Parmesan\n2 tbsp Parsley\nBlack Pepper','Cook pasta according to package instructions in a large pot of boiling water and salt. Add heavy cream and butter to a large skillet over medium heat until the cream bubbles and the butter melts. Whisk in parmesan and add seasoning (salt and black pepper). Let the sauce thicken slightly and then add the pasta and toss until coated in sauce. Garnish with parsley, and it\'s ready.',NULL,'https://www.youtube.com/watch?v=LPPcNPdq_j4','approved',0),
('Caribbean Tamarind balls','Add tamarind pulp and 1 cup granulated sugar to a bowl and mash together with a spoon or fork.','https://www.themealdb.com/images/media/meals/z1hz7z1765316430.jpg','Jamaican','General','Easy',15,70,8,'16 ounces Tamarind Pulp\n1 1/2 cups Sugar','Add tamarind pulp and 1 cup granulated sugar to a bowl and mash together with a spoon or fork. Take small amounts of the tamarind and sugar mix and shape them into small balls by rolling them in your hands. Make them the size of a marble or slightly bigger, as you like.\nAdd the remaining sugar to a flat surface, like a plate or a sheet pan. Roll the tamarind balls in granulated sugar until they\'re well-coated.\nYou can eat the tamarind balls immediately, or you can let them set for a few hours or overnight. Allowing them to set will give them a firmer texture and more crystallized sugar coating. Enjoy.',NULL,'https://www.youtube.com/watch?v=adRA-90CHUE','approved',0),
('Japanese Katsudon','STEP 1 Heat the oil in a pan, fry the sliced onion until golden brown, then add the tonkatsu (see recipe here), placing it in the middle of the pan.','https://www.themealdb.com/images/media/meals/d8f6qx1604182128.jpg','Japanese','General','Medium',5,30,4,'1 tbs Vegetable Oil\n1 large Onion\n1 chopped Pork\n150ml Vegetable Stock\n1 tbs Soy Sauce\n1 tsp Mirin\n1 tsp Sugar\n2 Beaten Eggs\n200g Sushi Rice\nChopped Chives','STEP 1\nHeat the oil in a pan, fry the sliced onion until golden brown, then add the tonkatsu (see recipe here), placing it in the middle of the pan. Mix the dashi, soy, mirin and sugar together and tip three-quarters of the mixture around the tonkatsu. Sizzle for a couple of mins so the sauce thickens a little and the tonkatsu reheats.\n\nSTEP 2\nTip the beaten eggs around the tonkatsu and cook for 2-3 mins until the egg is cooked through but still a little runny. Divide the rice between two bowls, then top each with half the egg and tonkatsu mix, sprinkle over the chives and serve immediately, drizzling with a little more soy if you want an extra umami kick.',NULL,'https://www.youtube.com/watch?v=voE-MBJqBVk','approved',0),
('Sukuma Wiki','Heat the 2 tablespoons of oil in a large skillet or pot over medium heat until shimmering.','https://www.themealdb.com/images/media/meals/60o82j1762341177.jpg','Kenyan','Vegetarian','Easy',10,50,4,'2 tablespoons Oil\n2 medium Red Onions\n1 lb Kale\nDash Salt\n1 cup Double Cream','Heat the 2 tablespoons of oil in a large skillet or pot over medium heat until shimmering. Add the onions and cook, stirring occasionally, until softened, 5 to 7 minutes.\nAdd the shredded kale to the onions and mix well. Turn the heat to medium-low, cover and cook for 5 minutes.\nAfter 5 minutes, remove the lid, add salt to taste, and stir in the cream. Continue cooking for another 5 minutes, uncovered, stirring occasionally. The cream will thicken slightly, making for a deliciously rich creamed kale and onions. Yumm!\nServe it up with your favorite Kenyan stew, and a side of ugali!',NULL,'https://www.youtube.com/watch?v=02hHtPDAxOs','approved',0),
('Laksa King Prawn Noodles','Heat the oil in a medium saucepan and add the chilli.','https://www.themealdb.com/images/media/meals/rvypwy1503069308.jpg','Malaysian','General','Medium',20,70,4,'1 tbsp Olive Oil\n1 finely sliced Red Chilli\n2 ½ tbsp Thai red curry paste\n1 vegetable stock cube\n400ml can coconut milk\n2 tsp fish sauce\n100g rice noodles\n2 juice of 1, the other halved lime\n150g king prawns\n½ small pack coriander','Heat the oil in a medium saucepan and add the chilli. Cook for 1 min, then add the curry paste, stir and cook for 1 min more. Dissolve the stock cube in a large jug in 700ml boiling water, then pour into the pan and stir to combine. Tip in the coconut milk and bring to the boil.\nAdd the fish sauce and a little seasoning. Toss in the noodles and cook for a further 3-4 mins until softening. Squeeze in the lime juice, add the prawns and cook through until warm, about 2-3 mins. Scatter over some of the coriander.\nServe in bowls with the remaining coriander and lime wedges on top for squeezing over.',NULL,'https://www.youtube.com/watch?v=OcarztU8cYo','approved',0),
('Moroccan Carrot Soup','Step 1 Preheat oven to 180° C. Step 2 Combine carrots, onion, garlic, cumin seeds, coriander seeds, salt and olive oil in a bowl and mix well.','https://www.themealdb.com/images/media/meals/jcr46d1614763831.jpg','Moroccan','Vegetarian','Medium',10,20,4,'6 chopped Carrots\n1 sliced Onion\n4 Garlic Clove\n1 tsp Cumin\n1/2 tsp Coriander\n1 tbs Olive Oil\n1/4 tsp Garam Masala\n1 tsp Lemon Juice','Step 1\nPreheat oven to 180° C.\nStep 2\nCombine carrots, onion, garlic, cumin seeds, coriander seeds, salt and olive oil in a bowl and mix well. Transfer on a baking tray.\nStep 3\nPut the baking tray in preheated oven and roast for 10-12 minutes or till carrots soften. Remove from heat and cool.\nStep 4\nGrind the baked carrot mixture along with some water to make a smooth paste and strain in a bowl.\nStep 5\nHeat the carrot mixture in a non-stick pan. Add two cups of water and bring to a boil. Add garam masala powder and mix. Add salt and mix well.\nStep 6\nRemove from heat, add lemon juice and mix well.\nStep 7\nServe hot.',NULL,'https://www.youtube.com/watch?v=7tDWOpnIhok','approved',0),
('Braised stuffed cabbage','step 1 Heat oven to 180C/fan 160C/gas 4.','https://www.themealdb.com/images/media/meals/z267f71764364072.jpg','Polish','Vegetarian','Hard',10,10,4,'6 large Cabbage Leaves\n2 tablespoons Olive Oil\n1 chopped Onion\n2 tsp Rosemary\n1 chopped Celery\n140g Basmati Rice\n140g Cooked Chestnut\n50g Cranberry\n300ml Vegetable Stock\n1 tablespoon Balsamic Vinegar\n1 tsp Clear Honey','step 1\nHeat oven to 180C/fan 160C/gas 4. Remove the tough central stalk from the cabbage leaves. Bring a large pan of salted water to the boil, add the cabbage, then cook for just 1-2 mins until the leaves are starting to wilt. Drain and refresh under cold running water. Drain well, then pat dry with a tea towel.\n\nstep 2\nHeat the oil in a pan, add the onion, then fry for 5 mins until slightly browned. Add the rosemary and celery, then cook for 8 mins more. Stir in the rice, then cook for a min or so until the grains are glistening. Remove from the heat, stir in the chestnuts and cranberries, then season.\n\nstep 3\nSpoon a little stuffing onto a cabbage leaf, roll up and fold in the sides to enclose the filling. Put in a single layer in a large, oiled, shallow ovenproof dish with the join underneath. Fill the remaining leaves in the same way. Mix the stock, vinegar and honey, then pour over the cabbage. Cover the dish tightly with foil, bake for 1 hr, uncover, then cook for a further 15 mins.',NULL,'https://www.youtube.com/watch?v=RNrZpQaj5us','approved',0),
('Portuguese barbecued pork (Febras assadas)','STEP 1 Cut the tenderloins into 5 equal-size pieces leaving the tail ends a little longer.','https://www.themealdb.com/images/media/meals/cybyue1614349443.jpg','Portuguese','General','Medium',25,60,4,'2 Pork\n200ml White Wine\n1/2 tsp Paprika\n2 Lemon\n1/2 Lemon Juice\nDash Olive Oil\nTo serve Mayonnaise\n1 kg Potatoes\nFor frying Vegetable Oil','STEP 1\n\nCut the tenderloins into 5 equal-size pieces leaving the tail ends a little longer. Take a clear plastic bag and slip one of the pieces in. Bash it into an escalope the size of a side-plate with a rolling pin and repeat with the remaining pieces.\n\nSTEP 2\n\nPut the wine, paprika, some salt and pepper and the juice of ½ a lemon in a bowl and add the pork. Leave to marinate for 20-30 minutes, while you get your barbecue to the stage where the coals are glowing but there are no flames.\n\nSTEP 3\n\nTo make the chips, fill a basin with cool water and cut the potatoes into 3cm-thick chips. Soak them in the water for 5 minutes and then change the water. Leave for 5 more minutes. Drain and then pat dry on a towel or with kitchen paper.\n\nSTEP 4\n\nHeat the oil in a deep fryer or a deep heavy-based pan with a lid to 130C and lower the chips into the oil (in batches). Blanch for 8-10 minutes. Remove from the oil and drain well. Place on a tray to cool. Reheat the oil to 180C (make sure it’s hot or your chips will be soggy) and lower the basket of chips into the oil (again, do this in batches). Leave to cook for 2 minutes and then give them a little shake. Cook for another minute or so until they are well coloured and crisp to the touch. Drain well for a few minutes, tip into a bowl and sprinkle with sea salt.\n\nSTEP 5\n\nThe pork will cook quickly so do it in 2 batches. Take the pieces out of the marinade, rub them with oil, and drop them onto the barbecue (you could also use a chargrill). Cook for 1 minute on each side – they may flare up as you do so. This should really be enough time as they will keep on cooking. Take them off the barbecue and pile onto a plate. Repeat with the remaining batch.\n\nSTEP 6\n\nServe by piling a plate with chips, drop the pork on top of each pile and pouring the juices from the plate over so the chips take up the flavours. Top with a spoon of mayonnaise and a wedge of lemon.',NULL,'https://www.youtube.com/watch?v=tVpsZaejyYU','approved',0),
('Fish Soup (Ukha)','In a medium pot, heat the olive oil over medium-high heat.','https://www.themealdb.com/images/media/meals/7n8su21699013057.jpg','Russian','General','Medium',20,60,4,'2 tbs Olive Oil\n1 sliced Onion\n2 medium Carrots\n3 cups Fish Stock\n3 cups Water\n4 large Potatoes\n3 Bay Leaf\n1 Cod\n1 Salmon','In a medium pot, heat the olive oil over medium-high heat. Add the onions and cook, stirring occasionally until the onions start to caramelize. Add the carrots and cook until the carrots start to soften, about 4 more minutes.\nAdd the stock, water, potatoes, bay leaves, and black peppercorns. Season with salt and bring to a boil. Reduce heat, cover and cook for 10 minutes. Add the millet and cook for 15 more minutes until millet and potatoes are cooked.\nGently add the fish cubes. Stir and bring the soup to a simmer. The fish will cook through very fast, so make sure to not overcook them. They are done when the flesh is opaque and flakes easily.\nGarnish the soup with chopped fresh dill or parsley before serving.',NULL,'https://www.youtube.com/watch?v=cS3Yn-y5uVg','approved',0),
('Mamoul (Eid biscuits)','1 Mix butter with sugar until creamy.','https://www.themealdb.com/images/media/meals/35kejr1763599712.jpg','Saudi Arabian','General','Easy',10,10,8,'300g Plain Flour\n200g Semolina\n25g Sunflower Oil\n250g Unsalted Butter\n50 ml Milk\n60g Icing Sugar','1\nMix butter with sugar until creamy.\n2\nAdd oil flour and semolina and mix.\n3\nAdd warm milk and don\'t knead too much\n4\nCover and leave aside for an hour or less until you prepare the filling\n5\nFor the dates filling, fry some sesame in a pan then add butter. Add the dates paste and mixed well with sesame and butter. Then add a little bit of water until it\'s mushy. Be careful don\'t make it too mushy.\n6\nTake it of the pan, put in a plate until it\'s cool. Then start to shape balls that weigh 15 gm.\n7\nRefrigerate for 1/2 an hour.\n8\nGet back to the dough and shape it as balls that weigh 30 gm.\n9\nTake the date filling out of the fridge and start to stuff each dough ball with dates ball.\nThen use the mamoul mould to give it this shape.\n10\nIn a preheated oven 180 degrees, put it for 20 minutes until golden from below and little bit golden from above.',NULL,'https://www.youtube.com/watch?v=RqBeOaXvqGM','approved',0),
('Arroz con gambas y calamar','step 1 Peel and devein most of the prawns (a fishmonger should be able to do this for you), keeping a few whole for decoration, if you like.','https://www.themealdb.com/images/media/meals/jc6oub1763196663.jpg','Spanish','General','Medium',30,40,4,'24 Raw King Prawns\n2 tbsp Olive Oil\n1 small Onion\n1 Bay Leaf\n1 pinch Saffron\n450g Paella Rice\n2 teaspoons Tomato Puree\n200ml White Wine\n650ml Seafood stock\n3 Medium Squid','step 1\nPeel and devein most of the prawns (a fishmonger should be able to do this for you), keeping a few whole for decoration, if you like. Heat the olive oil in a large frying pan or shallow flameproof casserole over a medium-low heat and fry the onion for 5 mins until softened. Add the bay leaf, saffron, rice and tomato purée, and cook for 1-2 mins more, stirring.\n\nstep 2\nPour in the wine and bubble for 1-2 mins, then pour in the seafood stock and 150ml water. Cook for 5 mins, then add the squid, season well and stir to combine. Bring to the boil, then cover and reduce the heat to a gentle simmer. Cook for 12 mins more, adding a little more water if the mixture starts to look dry.\n\nstep 3\nUncover the pan and stir through the peeled prawns, then arrange any whole prawns on top of the rice mixture. Cover again and simmer for a further 5-6 mins until the prawns are pink and cooked through. Leave to stand for a couple of minutes before serving from the pan.',NULL,'https://www.youtube.com/watch?v=nFFp0ebOlOo','approved',0),
('Syrian Bread','Place ingredients in the pan of the bread machine in the order recommended by the manufacturer.','https://www.themealdb.com/images/media/meals/54xzk31760524666.jpg','Syrian','General','Easy',10,20,4,'1 and 1/8 cup Water\n2 tblsp Vegetable Oil\n1/2 teaspoon Sugar\n1 1/2 tsp Salt\n3 Cups Flour\n1 1/2 tsp Yeast','Place ingredients in the pan of the bread machine in the order recommended by the manufacturer. Select Dough cycle; press Start.\n\nWhen the Dough cycle is almost complete, preheat the oven to 475 degrees F (245 degrees C).\n\nTurn dough out onto a lightly floured surface. Divide into eight equal pieces and form into rounds. Cover the rounds with a damp cloth and let rest.\n\nRoll dough into thin flat circles, about 8 inches in diameter. Cook two at a time on preheated baking sheets or a baking stone until puffed up and golden brown, about 5 minutes. Repeat for remaining loaves.',NULL,'https://www.youtube.com/watch?v=Pjzj0dws0Yk','approved',0),
('Pad See Ew','Mix Sauce in small bowl. Mince garlic into wok with oil.','https://www.themealdb.com/images/media/meals/uuuspp1468263334.jpg','Thai','General','Hard',25,20,4,'6oz/180g rice stick noodles\n2 tbsp dark soy sauce\n2 tbsp oyster sauce\n2 tsp soy sauce\n2 tsp white vinegar\n2 tsp sugar\n2 tbsp water\n2 tbsp peanut oil\n2 cloves garlic\n1 cup Chicken\n1 Egg\n4 cups Chinese broccoli','Mix Sauce in small bowl.\nMince garlic into wok with oil. Place over high heat, when hot, add chicken and Chinese broccoli stems, cook until chicken is light golden.\nPush to the side of the wok, crack egg in and scramble. Don\'t worry if it sticks to the bottom of the wok - it will char and which adds authentic flavour.\nAdd noodles, Chinese broccoli leaves and sauce. Gently mix together until the noodles are stained dark and leaves are wilted. Serve immediately!',NULL,'https://www.youtube.com/watch?v=Ohy1DELF4is','approved',0),
('Keleya Zaara','Heat the vegetable oil in a large frying pan over medium-high heat.','https://www.themealdb.com/images/media/meals/8x09hy1560460923.jpg','Tunisian','General','Medium',5,60,4,'4 tbs Olive Oil\n750g Lamb\n1 1/2 tsp Saffron\n1 Large Chopped Onion\n25 ml Water\n30g Parsley\n1 tbs Butter\n1 Lemon','Heat the vegetable oil in a large frying pan over medium-high heat. Add the lamb and cook until browned on all sides, about 5 minutes. Season with saffron, salt and pepper to taste; stir in all but 4 tablespoons of the onion, and pour in the water. Bring to the boil, then cover, reduce heat to medium-low, and simmer until the lamb is tender, about 15 minutes.\nUncover the pan, stir in the butter and allow the sauce reduce 5 to 10 minutes to desired consistency. Season to taste with salt and pepper, then pour into a serving dish. Sprinkle with the remaining chopped onions and parsley. Garnish with lemon wedges to serve.',NULL,'https://www.youtube.com/watch?v=u_OSIChzuL0','approved',0),
('Aubergine couscous salad','step 1 Heat grill to high. Put the aubergine on a baking sheet, brush with oil and season.','https://www.themealdb.com/images/media/meals/02s6gc1763799560.jpg','Turkish','Vegetarian','Medium',30,50,4,'1 sliced Aubergine\n3  tablespoons Olive Oil\n140g Couscous\n225g Vegetable Stock\n200g Cherry Tomatoes\nHandful Mint\n100g Goats Cheese\nJuice of 1/2 Lemon','step 1\nHeat grill to high. Put the aubergine on a baking sheet, brush with oil and season. Grill for about 15 mins, turning and brushing with more oil halfway, until browned and softened.\n\nstep 2\nMeanwhile, tip the couscous into a large bowl, pour over the stock, then cover and leave for 10 mins. Mix the tomatoes, mint, goat’s cheese and remaining oil together. Fluff the couscous up with a fork, then stir in the aubergines, tomato mixture and lemon juice.',NULL,'https://www.youtube.com/watch?v=8ws2Ohy__CQ','approved',0),
('Borsch','step 1 To make the stock, put the meat, whole onion, bay leaf and 2 litres of lightly salted cold water in a large saucepan.','https://www.themealdb.com/images/media/meals/804v1j1764367088.jpg','Ukrainian','General','Hard',10,70,4,'1kg Beef Shin\n1 Onion\n1 Bay Leaf\n2.5kg Potatoes\n2 tablespoons Sunflower Oil\n1 Diced Onion\n1 Carrots\n200g Beetroot\n1 chopped Red Pepper\n200g Tinned Tomatos\n6 Prunes\n1/2 White Cabbage\n400g Kidney Beans\n100 ml Creme Fraiche\nBunch Dill\nTo serve Crusty Bread','step 1\nTo make the stock, put the meat, whole onion, bay leaf and 2 litres of lightly salted cold water in a large saucepan. Cook over a very low heat for 1 hr 30 mins or until the beef shin is soft and falls apart easily – this can take up to 3 hrs. Skim off the scum with a spoon from time to time. Break up any larger pieces of beef into the broth, remove the whole onion and discard.\n\nstep 2\nAdd the potatoes to the borscht, season well with salt and pepper and cook for 10-15 mins until tender. Meanwhile, heat the sunflower oil in a large, deep frying pan. Add the diced onion and carrot, and cook over a medium heat, stirring, until the carrot is soft and is about to start caramelising.\n\nstep 3\nAdd the beetroot and cook for around 5 mins, stirring occasionally. Add the red pepper, if using, and cook for another 2 mins, then add the tomatoes and prunes, stir, then increase the heat and boil to reduce slightly, before adding everything to the borscht.\n\nstep 4\nAdd the shredded cabbage and the kidney beans, and cook for 7-10 mins or until tender. Serve with a dollop of sour cream or crème fraîche, lots of chopped dill and some crusty bread.',NULL,'https://www.youtube.com/watch?v=6CXgPVw_-0g','approved',0),
('Chocolate alfajores','For the cookies cream the butter with the sugar for a few minutes.','https://www.themealdb.com/images/media/meals/k9o0xr1764373018.jpg','Uruguayan','General','Hard',25,20,8,'150g Butter\n70g Sugar\n1 Egg\n25g Honey\n175g All purpose flour\n80g Cornstarch\n30g Unsweetened Cocoa\n1 tsp Baking Powder\n1 tsp Baking Powder\n400g Dulce de leche\n500g Milk Chocolate\n100g Butter\nZest of 1 Orange','For the cookies cream the butter with the sugar for a few minutes. Then add the egg and honey and mix well. Add flour, cornstarch, cocoa, baking soda and baking powder and mix until you get a dough. Wrap in plastic wrap and chill for at least half an hour or overnight.\n\n2\nLine two baking sheets with parchment paper, preheat oven to 200 degrees Celsius.\n\n3\nDivide dough into two parts, put one part back in the fridge before using. Roll out second part to about 2 millimeters and cut out round cookies with 5-6 centimeters in diameter. This can be done with a cookie cutter or glass. You should get 30 cookies in total or even more, I get about 40. Bake one baking sheet at the time for about 8-10min. Let cookies cool.\n\n4\nFor the filling look for two cookies of the same size and place about one teaspoon of dulce de leche onto the bottom one before sandwiching together.\n\n5\nChop semi-sweet chocolate and melt with butter and orange zest on low heat. Dunk each sandwich cookie into the chocolate and let cool off on parchment paper before serving.',NULL,'https://www.youtube.com/watch?v=ucBoYab5tXY','approved',0);
